functions.showToolAuthorStudio:
function showToolAuthorStudio() {
  var out = document.getElementById("output");
  out.innerHTML = "";
  out.classList.remove("hidden");
  if (typeof createConfigHeader === "function") {
    var header = createConfigHeader("ADMIN", "🔧", "Tool Author Studio", { marginBottom: "10px" });
    out.appendChild(header);
  }
  var tabBar = document.createElement("div");
  tabBar.style.cssText = "display:flex; gap:0; margin:0 12px 10px 12px; border-bottom:2px solid #e2e8f0;";
  var content = document.createElement("div");
  content.style.cssText = "padding:0 12px 12px 12px;";
  out.appendChild(tabBar);
  out.appendChild(content);
  var tabs = [
    // Tile tab removed — its functionality is folded into Tools (each tool's
    // edit card has source + tool settings + tile settings together).
    { id: "tool",    label: "🧩 Tools",       render: _tasToolEditorTab },
    { id: "data",    label: "📚 Data",        render: _tasDataTab },
    { id: "bundles", label: "📦 Bundles",     render: _tasBundlesTab },
    { id: "create",  label: "✨ AI Create",   render: _tasAiCreateTab },
    { id: "fix",     label: "🔧 AI Fix",      render: _tasAiFixTab },
    { id: "io",      label: "📦 Import/Export", render: _tasImportExportTab },
    { id: "history", label: "🕒 History",     render: _tasHistoryTab },
  ];
  var activeTab = "tool";
  function paintTabs() {
    tabBar.innerHTML = "";
    tabs.forEach(function (t) {
      var btn = document.createElement("div");
      var on = activeTab === t.id;
      btn.style.cssText = "flex:1; text-align:center; padding:8px 4px; font-size:10px; font-weight:700; cursor:pointer; transition:all 0.2s; white-space:nowrap; " +
        (on ? "background:#fff; color:#1565c0; border-bottom:3px solid #1565c0; margin-bottom:-2px;" : "background:#f8fafc; color:#64748b; border-bottom:3px solid transparent;");
      btn.textContent = t.label;
      btn.onclick = function () {
        activeTab = t.id;
        paintTabs();
        content.innerHTML = "";
        t.render(content);
      };
      tabBar.appendChild(btn);
    });
  }
  paintTabs();
  // Initial render
  tabs.find(function (t) { return t.id === activeTab; }).render(content);
  if (typeof window.createPlatinumHomeBtn === "function") out.appendChild(window.createPlatinumHomeBtn());
}

functions._tasToolEditorTab:
function _tasToolEditorTab(content) {
  content.innerHTML = '<div style="padding:14px; text-align:center; font-size:11px; color:#94a3b8;">Loading tools…</div>';
  loadFeatureData(STORE_JSON_TOOLS).then(function (rows) {
    var tools = (rows || []).filter(function (r) { return r && r.id && String(r.id).indexOf("__") !== 0; });
    if (tools.length === 0) {
      content.innerHTML = '<div style="padding:24px; text-align:center; font-size:11px; color:#64748b; background:#f8fafc; border:1px dashed #cbd5e1;">No tools installed. Install via Settings → Tool Manager.</div>';
      return;
    }
    tools.sort(function (a, b) {
      var ta = ((a.catalog && a.catalog.title) || a.label || a.id).toLowerCase();
      var tb = ((b.catalog && b.catalog.title) || b.label || b.id).toLowerCase();
      return ta < tb ? -1 : ta > tb ? 1 : 0;
    });
    var installedById = {};
    tools.forEach(function (t) { installedById[t.id] = t; });
    // Bundle membership — same source as Tool Manager (window._eliBundles
    // populated by _eliCheckForToolUpdates AND refreshed by Bundles-tab push).
    var bundles = (window._eliBundles || []).slice();
    var toolToBundles = {};
    bundles.forEach(function (b) {
      if (!Array.isArray(b.tools)) return;
      b.tools.forEach(function (toolId) {
        if (!toolToBundles[toolId]) toolToBundles[toolId] = [];
        toolToBundles[toolId].push(b);
      });
    });
    function inAnyBundle(toolId) { return !!toolToBundles[toolId]; }
    var standaloneTools = tools.filter(function (t) { return !inAnyBundle(t.id); });
    function renderToolRow(t, idx) {
      var stripe = idx % 2 === 0 ? "#fff" : "#f8fafc";
      var ic = (t.catalog && t.catalog.icon) || "🧩";
      var lab = (t.catalog && t.catalog.title) || t.label || t.id;
      var cat = (t.catalog && t.catalog.category) || "(no category)";
      var ver = t.__version != null && t.__version !== "" ? String(t.__version) : "";
      var fnCount = t.functions ? Object.keys(t.functions).length : 0;
      var defaultOn = t.defaultEnabled !== false;
      var hidden = !!(t.catalog && t.catalog.hidden);
      var enabledChip = defaultOn
        ? '<span style="display:inline-block; padding:2px 7px; font-size:9px; font-weight:700; background:#dcfce7; color:#166534; border:1px solid #86efac;">✓ ON DEFAULT</span>'
        : '<span style="display:inline-block; padding:2px 7px; font-size:9px; font-weight:700; background:#fef3c7; color:#92400e; border:1px solid #fde68a;">🔕 OFF DEFAULT</span>';
      var menuChip = hidden
        ? '<span style="display:inline-block; padding:2px 7px; font-size:9px; font-weight:700; background:#fff; color:#94a3b8; border:1px solid #cbd5e1;">🚫 HIDDEN</span>'
        : '<span style="display:inline-block; padding:2px 7px; font-size:9px; font-weight:700; background:#eef4ff; color:#1e40af; border:1px solid #bfdbfe;">👁 IN MENUS</span>';
      var inBundles = toolToBundles[t.id] || [];
      var bundleChips = inBundles.map(function (b) {
        return '<span style="display:inline-block; padding:2px 7px; font-size:9px; font-weight:700; background:#faf5ff; color:#6b21a8; border:1px solid #c4b5fd;" title="Member of bundle: ' + _ebEsc(b.id) + '">📦 ' + _ebEsc(b.label || b.id) + '</span>';
      }).join("");
      return (
        '<div data-tas-tool-row="' + _ebEsc(t.id) + '" style="background:' + stripe + '; border:1px solid #e2e8f0; padding:10px 12px; margin-bottom:5px;">' +
        '<div style="display:flex; justify-content:space-between; align-items:flex-start; gap:8px;">' +
        '<div style="flex:1; min-width:0; cursor:pointer;" data-tas-edit-area="' + _ebEsc(t.id) + '">' +
        '<div style="font-size:13px; font-weight:700; color:#0f172a;">' + ic + ' ' + _ebEsc(lab) +
          (ver ? ' <span style="font-size:10px; font-weight:500; color:#1565c0;">v' + _ebEsc(ver) + '</span>' : '') +
        '</div>' +
        '<div style="font-size:9.5px; color:#64748b; margin-top:2px;">' + _ebEsc(t.id) + ' · ' + _ebEsc(cat) + ' · ' + fnCount + ' fn</div>' +
        '<div style="display:flex; gap:5px; margin-top:5px; flex-wrap:wrap;">' + enabledChip + menuChip + bundleChips + '</div>' +
        '</div>' +
        '<div style="display:flex; gap:4px; flex-shrink:0;">' +
        '<button data-tas-edit="' + _ebEsc(t.id) + '" title="Edit source, settings, and tile in one card" style="padding:5px 10px; font-size:10px; cursor:pointer; background:#1565c0; color:#fff; border:none; font-weight:700;">📝 Edit</button>' +
        '<button data-tas-push="' + _ebEsc(t.id) + '" title="Push current state to CDN" style="padding:5px 10px; font-size:10px; cursor:pointer; background:linear-gradient(135deg,#16a34a,#15803d); color:#fff; border:none; font-weight:700;">🚀 Push</button>' +
        '</div>' +
        '</div>' +
        '</div>'
      );
    }
    function renderUninstalledMember(memberId) {
      return '<div style="background:#fff; border:1px dashed #cbd5e1; padding:8px 12px; margin-bottom:5px; font-size:11px; color:#64748b;">' +
        '<span style="font-weight:700;">' + _ebEsc(memberId) + '</span>' +
        ' <span style="color:#94a3b8;">— not installed locally; can\'t edit here. Install via Tool Manager to edit.</span>' +
      '</div>';
    }
    var html = '<div style="font-size:11px; color:#64748b; margin-bottom:10px; line-height:1.5;">' +
      '<strong style="color:#0f172a;">' + tools.length + ' tool(s)</strong>' +
      (bundles.length ? ' across <strong>' + bundles.length + ' bundle' + (bundles.length === 1 ? '' : 's') + '</strong>' : '') +
      '. Click a row to edit source, settings, and tile in one place.' +
      '</div>';
    // ─── Bundles section ─────────────────────────────────────────────────
    if (bundles.length > 0) {
      bundles.sort(function (a, b) { return (a.label || a.id || "").localeCompare(b.label || b.id || ""); });
      html += '<div style="margin-top:6px; padding:6px 10px; background:linear-gradient(135deg,#4c1d95,#5b21b6); color:#fff; font-size:10px; font-weight:800; text-transform:uppercase; letter-spacing:0.5px;">' +
        '📦 Bundles (' + bundles.length + ')' +
        '</div>';
      bundles.forEach(function (b) {
        var bIc = b.icon || "📦";
        var bLab = b.label || b.id;
        var bDesc = b.desc || "";
        var memberIds = Array.isArray(b.tools) ? b.tools : [];
        var installedMembers = memberIds.filter(function (id) { return !!installedById[id]; });
        var uninstalledMembers = memberIds.filter(function (id) { return !installedById[id]; });
        var bKey = "eli_tas_bundle_" + (b.id || "x").replace(/\W+/g, "_");
        // Bundles default to COLLAPSED (matches Tool Manager). Click to
        // expand. localStorage stores "0" when user explicitly opens.
        var collapsed = true;
        try {
          var stored = localStorage.getItem(bKey);
          if (stored === "0") collapsed = false;
        } catch (_) {}
        html += '<details data-tas-bundle-key="' + _ebEsc(bKey) + '"' + (collapsed ? '' : ' open') + ' style="margin-bottom:8px; border:1px solid #c4b5fd; background:#faf5ff;">';
        html += '<summary style="cursor:pointer; padding:10px 12px; user-select:none; list-style:none; display:flex; justify-content:space-between; align-items:flex-start; gap:8px;">' +
          '<div style="flex:1; min-width:0;">' +
            '<div style="font-size:13px; font-weight:800; color:#4c1d95;">' + bIc + ' ' + _ebEsc(bLab) + '</div>' +
            (bDesc ? '<div style="font-size:10px; color:#6b21a8; margin-top:2px;">' + _ebEsc(bDesc) + '</div>' : '') +
            '<div style="font-size:10px; color:#7c3aed; margin-top:4px; font-weight:700;">' +
              installedMembers.length + ' / ' + memberIds.length + ' installed' +
              (uninstalledMembers.length ? ' · ' + uninstalledMembers.length + ' not installed' : '') +
            '</div>' +
          '</div>' +
          '<button data-tas-bundle-edit="' + _ebEsc(b.id) + '" title="Edit bundle metadata + members in the Bundles tab" style="padding:5px 10px; font-size:10px; cursor:pointer; background:#fff; color:#6b21a8; border:1px solid #c4b5fd; font-weight:700; flex-shrink:0;">⚙️ Edit bundle</button>' +
        '</summary>';
        html += '<div style="padding:8px;">';
        // Group installed members by category — render flat if all share
        // one category (sub-headers are noise), bucketed otherwise.
        var byCat = {};
        installedMembers.forEach(function (id) {
          var t = installedById[id];
          var c = (t.catalog && t.catalog.category) || "(uncategorized)";
          if (!byCat[c]) byCat[c] = [];
          byCat[c].push(t);
        });
        var catKeys = Object.keys(byCat).sort(function (a, c) {
          if (a === "Tools - ELI Core") return -1;
          if (c === "Tools - ELI Core") return 1;
          if (a === "(uncategorized)") return 1;
          if (c === "(uncategorized)") return -1;
          return a.localeCompare(c);
        });
        // Always show category sub-headers inside an expanded bundle —
        // matches Tool Manager. Reinforces bundle → category → tool nesting.
        var rowIdx = 0;
        catKeys.forEach(function (c) {
          html += '<div style="margin:4px 0 4px 0; padding:3px 8px; background:#ede9fe; color:#5b21b6; font-size:9px; font-weight:800; text-transform:uppercase; letter-spacing:0.4px;">' +
            _ebEsc(c) +
            '</div>';
          byCat[c].forEach(function (t) {
            html += renderToolRow(t, rowIdx++);
          });
        });
        uninstalledMembers.forEach(function (id) {
          html += renderUninstalledMember(id);
        });
        html += '</div></details>';
      });
    }
    // ─── Standalone tools ────────────────────────────────────────────────
    if (standaloneTools.length > 0) {
      html += '<div style="margin-top:14px; padding:6px 10px; background:linear-gradient(135deg,#0f172a,#1e293b); color:#fff; font-size:10px; font-weight:800; text-transform:uppercase; letter-spacing:0.5px;">' +
        (bundles.length ? '🧩 Standalone tools (' + standaloneTools.length + ')' : '🧩 Tools (' + standaloneTools.length + ')') +
        '</div>';
      html += '<div style="padding:8px 0;">';
      standaloneTools.forEach(function (t, idx) {
        html += renderToolRow(t, idx);
      });
      html += '</div>';
    }
    content.innerHTML = html;
    function findTool(id) { return installedById[id]; }
    function open(id) { var t = findTool(id); if (t) _tasOpenToolForm(t, content); }
    content.querySelectorAll("[data-tas-edit]").forEach(function (b) {
      b.onclick = function (e) { e.stopPropagation(); open(b.getAttribute("data-tas-edit")); };
    });
    content.querySelectorAll("[data-tas-edit-area]").forEach(function (a) {
      a.onclick = function () { open(a.getAttribute("data-tas-edit-area")); };
    });
    content.querySelectorAll("[data-tas-push]").forEach(function (b) {
      b.onclick = function (e) { e.stopPropagation(); _tasPushToolToCdn(b.getAttribute("data-tas-push"), content); };
    });
    // "Edit bundle" button on each bundle row → jump to Bundles tab and
    // open that bundle's editor. Stash the target id; the Bundles tab
    // entry-point reads it and auto-opens. We search all divs inside
    // #output for one whose textContent exactly matches the tab label and
    // has no children (leaf div = the tab button itself, not a wrapper).
    // Earlier implementation used `#output > div` which grabbed the header
    // div (output's actual first child) instead of the tab bar.
    content.querySelectorAll("[data-tas-bundle-edit]").forEach(function (b) {
      b.onclick = function (e) {
        e.preventDefault();
        e.stopPropagation();
        try { window._tasJumpToBundleId = b.getAttribute("data-tas-bundle-edit"); } catch (_) {}
        var allDivs = document.querySelectorAll("#output div");
        for (var i = 0; i < allDivs.length; i++) {
          var d = allDivs[i];
          if (d.children.length !== 0) continue;
          if ((d.textContent || "").trim() === "📦 Bundles") {
            d.click();
            return;
          }
        }
      };
    });
    // Per-bundle collapse persistence
    content.querySelectorAll("details[data-tas-bundle-key]").forEach(function (d) {
      d.addEventListener("toggle", function () {
        var key = d.getAttribute("data-tas-bundle-key");
        try { localStorage.setItem(key, d.open ? "0" : "1"); } catch (_) {}
      });
    });
  });
}
// Unified edit card. Shows three collapsible sections — Source code, Tool
// settings, Tile settings — plus Save and Push buttons. All edits land on
// the same tool object and save together via _tasSaveTool (which mirrors
// catalog block to STORE_CATALOG and re-evals functions).
//   - Save → persists to local IDB only (no version bump, no CDN write)
//   - Push → opens the standard _tasPushToolToCdn modal (auto-bumps version,
//            uploads file + manifest entry)

functions._tasOpenToolForm:
function _tasOpenToolForm(tool, content) {
  var fnNames = tool.functions ? Object.keys(tool.functions) : [];
  var currentFnName = fnNames[0] || "";

  function paint() {
    var src = (tool.functions && tool.functions[currentFnName]) || "";
    var ic = (tool.catalog && tool.catalog.icon) || "🧩";
    var titleDisplay = (tool.catalog && tool.catalog.title) || tool.label || tool.id;
    var verDisplay = tool.__version != null && tool.__version !== "" ? String(tool.__version) : "1.0";
    var releasedDisplay = tool.releasedAt
      ? new Date(tool.releasedAt).toISOString().slice(0, 10)
      : "—";
    var sectionStyle = "background:#fff; border:1px solid #e2e8f0; border-top:none;";
    var summaryStyle = "cursor:pointer; padding:10px 14px; background:#f8fafc; font-size:11px; font-weight:800; color:#0f172a; text-transform:uppercase; letter-spacing:0.5px; user-select:none; list-style:none; border-bottom:1px solid #e2e8f0;";
    var html =
      '<button id="tasBack" style="margin-bottom:8px; padding:4px 10px; font-size:10px; cursor:pointer; background:#fff; border:1px solid #cbd5e1; color:#64748b;">← Back to list</button>' +
