      '<div style="background:linear-gradient(135deg,#0f172a,#1e293b); color:#fff; padding:12px 14px; border:1px solid #e2e8f0;">' +
        '<div style="font-size:14px; font-weight:800;">' + ic + ' ' + _ebEsc(titleDisplay) + '</div>' +
        '<div style="font-size:10px; color:#94a3b8; margin-top:3px;">id: <code style="color:#cbd5e1;">' + _ebEsc(tool.id) + '</code> · v' + _ebEsc(verDisplay) + ' · released ' + _ebEsc(releasedDisplay) + '</div>' +
      '</div>' +
      // ─── Source ────────────────────────────────────────────────────────
