        '<summary style="' + summaryStyle + '">📝 Source code · ' + fnNames.length + ' function' + (fnNames.length === 1 ? '' : 's') + '</summary>' +
        '<div style="padding:12px 14px;">' +
          '<div style="display:flex; gap:8px; align-items:center; margin-bottom:6px;">' +
            '<label style="font-size:10px; font-weight:700; color:#64748b; text-transform:uppercase;">Function:</label>' +
            '<select id="tasFnSel" style="flex:1; padding:5px; font-size:11px; border:1px solid #cbd5e1;">' +
              fnNames.map(function (n) { return '<option value="' + _ebEsc(n) + '"' + (n === currentFnName ? " selected" : "") + '>' + _ebEsc(n) + '</option>'; }).join("") +
            '</select>' +
            '<button id="tasValidate" style="padding:5px 12px; font-size:10px; font-weight:700; background:#fff; color:#0d9488; border:1px solid #0d9488; cursor:pointer;">🧪 Validate</button>' +
          '</div>' +
          '<textarea id="tasFnSrc" style="width:100%; min-height:280px; max-height:500px; padding:10px; font-family:ui-monospace,Consolas,monospace; font-size:11px; line-height:1.45; border:1px solid #cbd5e1; resize:vertical; box-sizing:border-box; white-space:pre; tab-size:2;">' + _ebEsc(src) + '</textarea>' +
          '<div id="tasValidateOut" style="font-size:10px; margin-top:6px; min-height:14px;"></div>' +
        '</div>' +
      '</details>' +
      // ─── Tool settings ─────────────────────────────────────────────────
      '<details style="' + sectionStyle + '">' +
        '<summary style="' + summaryStyle + '">⚙️ Tool settings · version, defaultEnabled, audience</summary>' +
        '<div style="padding:12px 14px;">' +
          _tasField("tasSetVersion", "Version (display label — auto-bumps on push, e.g. \"1.2\")", verDisplay, "text") +
          // (Label field removed — it edited tool.label, which was an unused
          // fallback never shown by any UI. The dashboard tile name lives
          // under Tile → Title in this same edit card.)
          '<label style="display:flex; align-items:flex-start; gap:8px; font-size:11px; color:#475569; margin:10px 0;">' +
            '<input type="checkbox" id="tasSetDefaultEnabled"' + (tool.defaultEnabled !== false ? " checked" : "") + ' style="margin-top:1px;">' +
            '<span><strong>Default to ON</strong> — load the tool\'s functions at boot. Unchecking + re-pushing turns it OFF for new installs AND for existing users on next update (one-way; users can flip back on via Tool Manager toggle).</span>' +
          '</label>' +
          // Audience block
          '<div style="margin-top:12px; padding:8px 10px; background:#fffbeb; border:1px solid #fde68a; border-left:3px solid #f59e0b; font-size:10.5px; color:#78350f; line-height:1.5;">' +
