            var current = Array.isArray(tool.audience) ? tool.audience : [];
            var customTags = current.filter(function (t) { return KNOWN_GROUPS.indexOf(t) === -1; });
            var html = '<label style="display:block; font-size:10px; font-weight:700; color:#64748b; margin:8px 0 3px 0; text-transform:uppercase; letter-spacing:0.3px;">Groups (check all that should see this tool)</label>' +
