              var label = g === "all" ? "🌐 All (everyone)" : g;
              html += '<label style="display:flex; align-items:center; gap:6px; font-size:11px; color:#475569; cursor:pointer;">' +
                '<input type="checkbox" data-tas-group-cb="' + _ebEsc(g) + '"' + (checked ? ' checked' : '') + ' style="margin:0; cursor:pointer;">' +
                _ebEsc(label) +
              '</label>';
            });
            html += '</div>';
            html += '<label style="display:block; font-size:10px; font-weight:700; color:#64748b; margin:8px 0 3px 0; text-transform:uppercase; letter-spacing:0.3px;">Other tags (comma-separated, custom audiences not in the list above)</label>' +
              '<input id="tasSetAudienceCustom" type="text" value="' + _ebEsc(customTags.join(", ")) + '" style="width:100%; padding:6px 8px; font-size:11px; border:1px solid #cbd5e1; box-sizing:border-box;">';
            return html;
          })() +
          '<label style="display:block; font-size:10px; font-weight:700; color:#64748b; margin:8px 0 3px 0; text-transform:uppercase; letter-spacing:0.3px;">Audience emails (one per line)</label>' +
          '<textarea id="tasSetAudienceEmails" placeholder="someone@colpal.com" style="width:100%; min-height:50px; padding:6px 8px; font-size:11px; border:1px solid #cbd5e1; box-sizing:border-box; font-family:ui-monospace,Consolas,monospace;">' + _ebEsc((Array.isArray(tool.audienceEmails) ? tool.audienceEmails.join("\n") : "")) + '</textarea>' +
          '<label style="display:block; font-size:10px; font-weight:700; color:#64748b; margin:8px 0 3px 0; text-transform:uppercase; letter-spacing:0.3px;">Audience email domains (one per line — e.g. @colpal.com)</label>' +
          '<textarea id="tasSetAudienceEmailDomains" placeholder="@colpal.com" style="width:100%; min-height:50px; padding:6px 8px; font-size:11px; border:1px solid #cbd5e1; box-sizing:border-box; font-family:ui-monospace,Consolas,monospace;">' + _ebEsc((Array.isArray(tool.audienceEmailDomains) ? tool.audienceEmailDomains.join("\n") : "")) + '</textarea>' +
          // Bundle membership — read-only chips showing which bundles this
          // tool belongs to. Edit membership via the Bundles tab editor
          // (single source of truth — keeps bundle.tools the authoritative list).
          (function () {
            var bs = (window._eliBundles || []).filter(function (b) {
              return Array.isArray(b.tools) && b.tools.indexOf(tool.id) !== -1;
