// repo/branch are read from the same localStorage keys ALP uses, so a single
// admin login covers both tools.

functions._tasGhGet:
function _tasGhGet(pat, repo, branch, filePath) {
  var url = "https://api.github.com/repos/" + repo + "/contents/" + filePath +
    "?ref=" + encodeURIComponent(branch) + "&t=" + Date.now();
  return fetch(url, {
    cache: "no-store",
    headers: {
      "Authorization": "Bearer " + pat,
      "Accept": "application/vnd.github+json",
      "X-GitHub-Api-Version": "2022-11-28",
    },
  }).then(function (r) {
    if (r.status === 404) return null;
    if (!r.ok) return r.text().then(function (t) { throw new Error("GET " + filePath + " failed: HTTP " + r.status + " · " + t.slice(0, 200)); });
    return r.json();
  });
}

functions._tasGhPut:
function _tasGhPut(pat, repo, branch, filePath, contentStr, message, existingSha) {
  var url = "https://api.github.com/repos/" + repo + "/contents/" + filePath;
  // UTF-8 → base64 (matches ALP's helper exactly, handles unicode correctly).
  var bytes = new TextEncoder().encode(contentStr);
  var bin = "";
  for (var i = 0; i < bytes.length; i++) bin += String.fromCharCode(bytes[i]);
  var body = { message: message, content: btoa(bin), branch: branch };
  if (existingSha) body.sha = existingSha;
  return fetch(url, {
    method: "PUT",
    headers: {
      "Authorization": "Bearer " + pat,
      "Accept": "application/vnd.github+json",
      "X-GitHub-Api-Version": "2022-11-28",
      "Content-Type": "application/json",
    },
    body: JSON.stringify(body),
  }).then(function (r) {
    if (!r.ok) return r.text().then(function (t) { throw new Error("PUT " + filePath + " failed: HTTP " + r.status + " · " + t.slice(0, 200)); });
    return r.json();
  });
}
