          } else if (entry.audienceEmails) {
            delete entry.audienceEmails;
          }
          if (Array.isArray(tool.audienceEmailDomains) && tool.audienceEmailDomains.length) {
            entry.audienceEmailDomains = tool.audienceEmailDomains;
          } else if (entry.audienceEmailDomains) {
            delete entry.audienceEmailDomains;
          }
        }
        manifest.lastUpdated = new Date().toISOString();
        var newManifestStr = JSON.stringify(manifest, null, 2);
        return _tasGhPut(pat, repo, branch, "tools-manifest-v2.json", newManifestStr, "[TAS] manifest: " + toolId + " v" + nextVer, mfFile.sha);
      }).then(function () {
        setStatus("✓ Pushed.");
        // Persist the bumped version to local IDB so the local copy stays in
        // sync with what's now on the CDN (otherwise next save would re-bump
        // from the pre-push number).
        return _tasSaveTool(tool);
      }).then(function () {
        showToast("✓ Pushed " + toolId + " v" + nextVer + " to CDN.", "success");
        overlay.remove();
        _tasToolEditorTab(content);
      }).catch(function (e) {
        setStatus("❌ " + (e && e.message ? e.message : String(e)));
        goBtn.disabled = false;
        cancelBtn.disabled = false;
      });
    };
  });
}

functions._tasBundlesTab:
function _tasBundlesTab(content) {
  var pat = "";
  var repo = "apndrewn/eli-data";
  var branch = "main";
  try { pat = localStorage.getItem("eli_alp_pat") || ""; } catch (_) {}
  try { repo = localStorage.getItem("eli_alp_repo") || repo; } catch (_) {}
  try { branch = localStorage.getItem("eli_alp_branch") || branch; } catch (_) {}
  if (!pat) {
    content.innerHTML =
      '<div style="padding:24px; text-align:center; font-size:11px; color:#92400e; background:#fffbeb; border:1px solid #fde68a;">' +
      '⚠️ No GitHub PAT set. Open <strong>Admin Library Publisher</strong> first and configure your PAT — Bundle authoring needs the same credentials to push manifest changes.' +
      '</div>';
    return;
  }
  content.innerHTML = '<div style="padding:14px; text-align:center; font-size:11px; color:#94a3b8;">Loading manifest…</div>';
  _tasGhGet(pat, repo, branch, "tools-manifest-v2.json").then(function (mfFile) {
    if (!mfFile || !mfFile.content) throw new Error("Manifest not found.");
    var b64 = String(mfFile.content).replace(/\s/g, "");
    var binStr = atob(b64);
    var bytes = new Uint8Array(binStr.length);
    for (var i = 0; i < binStr.length; i++) bytes[i] = binStr.charCodeAt(i);
    var manifest;
    try { manifest = JSON.parse(new TextDecoder("utf-8").decode(bytes)); }
    catch (e) { throw new Error("Manifest parse failed: " + e.message); }
    var allEntries = Array.isArray(manifest.tools) ? manifest.tools : [];
    var bundles = allEntries.filter(function (e) { return e && e.kind === "bundle"; });
    var allTools = allEntries.filter(function (e) { return e && e.kind !== "bundle" && e.kind !== "data"; });
    var allData = allEntries.filter(function (e) { return e && e.kind === "data"; });
    // Refresh local cache so other tabs (Tools tab, Tool Manager) see the
    // current bundle set without waiting for the next update check.
    try {
      window._eliBundles = bundles.slice();
      localStorage.setItem("eli_bundles", JSON.stringify(bundles));
    } catch (_) {}
    // If the user clicked "Edit bundle" on the Tools tab, auto-open that
    // bundle's editor here.
    var jumpId = "";
    try { jumpId = window._tasJumpToBundleId || ""; } catch (_) {}
    if (jumpId) {
      try { window._tasJumpToBundleId = ""; } catch (_) {}
      var jumpTarget = bundles.filter(function (b) { return b.id === jumpId; })[0];
      if (jumpTarget) {
        _tasOpenBundleEditor(content, manifest, mfFile.sha, JSON.parse(JSON.stringify(jumpTarget)), allTools, allData, /*isNew*/ false);
        return;
      }
    }
    _tasRenderBundleList(content, manifest, mfFile.sha, bundles, allTools, allData);
  }).catch(function (e) {
    content.innerHTML =
      '<div style="padding:24px; text-align:center; font-size:11px; color:#991b1b; background:#fef2f2; border:1px solid #fca5a5;">' +
      '❌ Couldn\'t load manifest: ' + _ebEsc(e && e.message ? e.message : String(e)) +
      '</div>';
  });
}

functions._tasRenderBundleList:
function _tasRenderBundleList(content, manifest, manifestSha, bundles, allTools, allData) {
  allData = allData || [];
  var headerHtml =
    '<div style="font-size:11px; color:#64748b; margin-bottom:10px; line-height:1.5;">' +
    '<strong style="color:#0f172a;">' + bundles.length + ' bundle' + (bundles.length === 1 ? '' : 's') + '.</strong> ' +
    'Bundles group tools + data libraries for a unified install/update experience. They\'re manifest-only — no file to push, just metadata.' +
    '</div>';
  var newBtnHtml =
    '<button id="tasBundleNew" style="padding:8px 14px; font-size:11px; font-weight:800; background:linear-gradient(135deg,#4c1d95,#5b21b6); color:#fff; border:none; cursor:pointer; margin-bottom:10px;">+ New bundle</button>';
  var rowsHtml = "";
  if (bundles.length === 0) {
    rowsHtml = '<div style="padding:24px; text-align:center; font-size:11px; color:#64748b; background:#f8fafc; border:1px dashed #cbd5e1;">' +
      'No bundles yet. Click <strong>+ New bundle</strong> above to create one.' +
      '</div>';
  } else {
    bundles.sort(function (a, b) { return (a.label || a.id || "").localeCompare(b.label || b.id || ""); });
    rowsHtml = bundles.map(function (b, idx) {
      var stripe = idx % 2 === 0 ? "#fff" : "#f8fafc";
      var ic = b.icon || "📦";
      var lab = b.label || b.id;
      var desc = b.desc || "";
      var toolCount = Array.isArray(b.tools) ? b.tools.length : 0;
      var dataCount = Array.isArray(b.data) ? b.data.length : 0;
      var memberSummary = toolCount + (toolCount === 1 ? ' tool' : ' tools') + (dataCount ? ' + ' + dataCount + (dataCount === 1 ? ' data lib' : ' data libs') : '');
      var aud = b.audience && b.audience.length ? b.audience.join(", ") : "(no tags)";
      var emails = (b.audienceEmails || []).length;
      var domains = (b.audienceEmailDomains || []).length;
      return (
        '<div data-tas-bundle-row="' + _ebEsc(b.id) + '" style="background:' + stripe + '; border:1px solid #c4b5fd; padding:10px 12px; margin-bottom:5px;">' +
        '<div style="display:flex; justify-content:space-between; align-items:flex-start; gap:8px;">' +
        '<div style="flex:1; min-width:0; cursor:pointer;" data-tas-bundle-edit="' + _ebEsc(b.id) + '">' +
        '<div style="font-size:13px; font-weight:800; color:#4c1d95;">' + ic + ' ' + _ebEsc(lab) + '</div>' +
        '<div style="font-size:10px; color:#6b21a8; margin-top:2px;">id: <code>' + _ebEsc(b.id) + '</code> · ' + memberSummary + ' · audience: ' + _ebEsc(aud) + (emails ? ' · ' + emails + ' email' + (emails === 1 ? '' : 's') : '') + (domains ? ' · ' + domains + ' domain' + (domains === 1 ? '' : 's') : '') + '</div>' +
        (desc ? '<div style="font-size:10px; color:#64748b; margin-top:2px;">' + _ebEsc(desc) + '</div>' : '') +
        '</div>' +
        '<div style="display:flex; gap:4px; flex-shrink:0;">' +
        '<button data-tas-bundle-edit-btn="' + _ebEsc(b.id) + '" style="padding:5px 10px; font-size:10px; cursor:pointer; background:#1565c0; color:#fff; border:none; font-weight:700;">📝 Edit</button>' +
        '<button data-tas-bundle-delete="' + _ebEsc(b.id) + '" title="Delete this bundle (members are not affected)" style="padding:5px 10px; font-size:10px; cursor:pointer; background:#fff; border:1px solid #dc2626; color:#dc2626; font-weight:700;">🗑️</button>' +
        '</div>' +
        '</div>' +
        '</div>'
      );
    }).join("");
  }
  content.innerHTML = headerHtml + newBtnHtml + rowsHtml;
  document.getElementById("tasBundleNew").onclick = function () {
    var draft = {
      id: "bundle_" + new Date().toISOString().replace(/[^0-9]/g, "").slice(0, 14),
      kind: "bundle",
      label: "",
      icon: "📦",
      desc: "",
      category: "Tools - ELI Core",
      audience: ["all"],
      tools: [],
      data: [],
    };
    _tasOpenBundleEditor(content, manifest, manifestSha, draft, allTools, allData, /*isNew*/ true);
  };
  function findBundle(id) { return bundles.filter(function (b) { return b.id === id; })[0]; }
  function openEdit(id) {
    var b = findBundle(id);
    if (!b) return;
    // Deep-clone so cancel doesn't mutate the in-memory list
    _tasOpenBundleEditor(content, manifest, manifestSha, JSON.parse(JSON.stringify(b)), allTools, allData, /*isNew*/ false);
  }
  content.querySelectorAll("[data-tas-bundle-edit]").forEach(function (el) {
    el.onclick = function (e) { e.stopPropagation(); openEdit(el.getAttribute("data-tas-bundle-edit")); };
  });
  content.querySelectorAll("[data-tas-bundle-edit-btn]").forEach(function (el) {
    el.onclick = function (e) { e.stopPropagation(); openEdit(el.getAttribute("data-tas-bundle-edit-btn")); };
  });
  content.querySelectorAll("[data-tas-bundle-delete]").forEach(function (el) {
    el.onclick = function (e) {
      e.stopPropagation();
      var id = el.getAttribute("data-tas-bundle-delete");
      var b = findBundle(id);
      if (!b) return;
      if (!window.confirm("Delete bundle '" + (b.label || b.id) + "'?\n\nMember tools are NOT affected — they remain in the manifest as standalone entries. Only the grouping is removed.")) return;
      _tasDeleteBundle(content, manifest, manifestSha, id);
    };
  });
}

functions._tasOpenBundleEditor:
function _tasOpenBundleEditor(content, manifest, manifestSha, bundle, allTools, allData, isNew) {
  allData = allData || [];
  var memberIds = Array.isArray(bundle.tools) ? bundle.tools.slice() : [];
  var dataIds = Array.isArray(bundle.data) ? bundle.data.slice() : [];
  // Group checkbox state matching the four onboarding groups + "all". Custom
  // tags (anything not in this list) live in a separate text input.
  var KNOWN_GROUPS = ["all", "External Innovation", "Commercial", "Litigation", "Patents"];
  function paint() {
    var sectionStyle = "background:#fff; border:1px solid #e2e8f0; border-top:none;";
    var summaryStyle = "cursor:pointer; padding:10px 14px; background:#f8fafc; font-size:11px; font-weight:800; color:#0f172a; text-transform:uppercase; letter-spacing:0.5px; user-select:none; list-style:none; border-bottom:1px solid #e2e8f0;";
    var html =
      '<button id="tasBundleBack" style="margin-bottom:8px; padding:4px 10px; font-size:10px; cursor:pointer; background:#fff; border:1px solid #cbd5e1; color:#64748b;">← Back to bundles</button>' +
      '<div style="background:linear-gradient(135deg,#4c1d95,#5b21b6); color:#fff; padding:12px 14px; border:1px solid #c4b5fd;">' +
        '<div style="font-size:14px; font-weight:800;">' + (isNew ? "📦 New Bundle" : ("📦 Edit: " + _ebEsc(bundle.label || bundle.id))) + '</div>' +
        '<div style="font-size:10px; color:#e9d5ff; margin-top:3px;">' + (isNew ? "Set metadata + pick member tool ids; push to publish to the manifest." : ("id: " + _ebEsc(bundle.id))) + '</div>' +
      '</div>' +
      // ─── Identity ──────────────────────────────────────────────────────
      '<details open style="' + sectionStyle + '">' +
        '<summary style="' + summaryStyle + '">🪪 Identity</summary>' +
        '<div style="padding:12px 14px;">' +
          (isNew
            ? _tasField("tasBundleId", "Bundle id (must start with \"bundle_\" — used in manifest)", bundle.id, "text")
            : '<div style="font-size:10px; color:#64748b; margin-bottom:8px;">Bundle id: <code>' + _ebEsc(bundle.id) + '</code> (cannot be changed once created)</div>') +
          _tasField("tasBundleLabel", "Label (the big name users see)", bundle.label || "", "text") +
          _tasField("tasBundleIcon", "Icon (emoji)", bundle.icon || "📦", "text") +
          _tasField("tasBundleDesc", "Description (short blurb shown under the bundle row)", bundle.desc || "", "text") +
          '<label style="display:block; font-size:10px; font-weight:700; color:#64748b; margin:8px 0 3px 0; text-transform:uppercase; letter-spacing:0.3px;">Category (groups bundles in the listing)</label>' +
          '<input id="tasBundleCategory" type="text" list="tasBundleCategoryOptions" value="' + _ebEsc(String(bundle.category || "")) + '" placeholder="Tools - ELI Core" style="width:100%; padding:6px 8px; font-size:11px; border:1px solid #cbd5e1; box-sizing:border-box;">' +
          '<datalist id="tasBundleCategoryOptions"><option value="Tools - ELI Core"><option value="Admin"><option value="Engagement"><option value="Accessibility"><option value="Patents"><option value="Data"></datalist>' +
        '</div>' +
      '</details>' +
      // ─── Audience ──────────────────────────────────────────────────────
      '<details style="' + sectionStyle + '">' +
        '<summary style="' + summaryStyle + '">👥 Audience (who sees this bundle)</summary>' +
        '<div style="padding:12px 14px;">' +
          '<div style="margin-bottom:10px; padding:8px 10px; background:#fffbeb; border:1px solid #fde68a; border-left:3px solid #f59e0b; font-size:10.5px; color:#78350f; line-height:1.5;">' +
            'Bundle audience is independent of member-tool audiences. A user only sees the bundle if they match HERE; even if they\'d normally see the individual member tools, the bundle row stays hidden.' +
          '</div>' +
          // Group checkboxes (matches the onboarding "Group" dropdown).
          (function () {
            var current = Array.isArray(bundle.audience) ? bundle.audience : [];
            var customTags = current.filter(function (t) { return KNOWN_GROUPS.indexOf(t) === -1; });
            var html = '<label style="display:block; font-size:10px; font-weight:700; color:#64748b; margin:0 0 3px 0; text-transform:uppercase; letter-spacing:0.3px;">Groups (check all that should see this bundle)</label>' +
              '<div style="display:grid; grid-template-columns:1fr 1fr; gap:4px 12px; padding:8px 10px; background:#f8fafc; border:1px solid #e2e8f0;">';
            KNOWN_GROUPS.forEach(function (g) {
              var checked = current.indexOf(g) !== -1;
              var label = g === "all" ? "🌐 All (everyone)" : g;
              html += '<label style="display:flex; align-items:center; gap:6px; font-size:11px; color:#475569; cursor:pointer;">' +
                '<input type="checkbox" data-tas-bundle-group-cb="' + _ebEsc(g) + '"' + (checked ? ' checked' : '') + ' style="margin:0; cursor:pointer;">' +
                _ebEsc(label) +
              '</label>';
            });
            html += '</div>';
            html += '<label style="display:block; font-size:10px; font-weight:700; color:#64748b; margin:8px 0 3px 0; text-transform:uppercase; letter-spacing:0.3px;">Other tags (comma-separated, custom audiences)</label>' +
              '<input id="tasBundleAudienceCustom" type="text" value="' + _ebEsc(customTags.join(", ")) + '" style="width:100%; padding:6px 8px; font-size:11px; border:1px solid #cbd5e1; box-sizing:border-box;">';
            return html;
          })() +
          '<label style="display:block; font-size:10px; font-weight:700; color:#64748b; margin:8px 0 3px 0; text-transform:uppercase; letter-spacing:0.3px;">Audience emails (one per line)</label>' +
          '<textarea id="tasBundleAudienceEmails" placeholder="someone@colpal.com" style="width:100%; min-height:50px; padding:6px 8px; font-size:11px; border:1px solid #cbd5e1; box-sizing:border-box; font-family:ui-monospace,Consolas,monospace;">' + _ebEsc((Array.isArray(bundle.audienceEmails) ? bundle.audienceEmails.join("\n") : "")) + '</textarea>' +
          '<label style="display:block; font-size:10px; font-weight:700; color:#64748b; margin:8px 0 3px 0; text-transform:uppercase; letter-spacing:0.3px;">Audience email domains (one per line — e.g. @colpal.com)</label>' +
          '<textarea id="tasBundleAudienceEmailDomains" placeholder="@colpal.com" style="width:100%; min-height:50px; padding:6px 8px; font-size:11px; border:1px solid #cbd5e1; box-sizing:border-box; font-family:ui-monospace,Consolas,monospace;">' + _ebEsc((Array.isArray(bundle.audienceEmailDomains) ? bundle.audienceEmailDomains.join("\n") : "")) + '</textarea>' +
        '</div>' +
      '</details>' +
      // ─── Tool Members ───────────────────────────────────────────────────
      '<details open style="' + sectionStyle + '">' +
        '<summary style="' + summaryStyle + '">🧩 Tool members · ' + memberIds.length + '</summary>' +
        '<div style="padding:12px 14px;">' +
          '<div style="font-size:10px; color:#64748b; margin-bottom:8px;">Check tools to include. Members can also be installed/updated standalone — bundles only group them in the UI.</div>' +
          '<div style="max-height:300px; overflow-y:auto; border:1px solid #e2e8f0;">' +
            allTools.map(function (t, idx) {
              var checked = memberIds.indexOf(t.id) !== -1;
              var stripe = idx % 2 === 0 ? "#fff" : "#f8fafc";
              return '<label data-tas-member-row style="display:flex; align-items:center; gap:8px; padding:6px 10px; background:' + stripe + '; border-bottom:1px solid #f1f5f9; cursor:pointer; font-size:11px;">' +
                '<input type="checkbox" data-tas-bundle-member="' + _ebEsc(t.id) + '"' + (checked ? ' checked' : '') + ' style="cursor:pointer; margin:0;">' +
                '<span style="font-weight:700; color:#0f172a;">' + _ebEsc(t.label || t.id) + '</span>' +
                '<span style="color:#94a3b8; font-family:ui-monospace,Consolas,monospace; font-size:10px;">' + _ebEsc(t.id) + '</span>' +
              '</label>';
            }).join("") +
          '</div>' +
        '</div>' +
      '</details>' +
      // ─── Data Library Members ───────────────────────────────────────────
      '<details style="' + sectionStyle + '">' +
        '<summary style="' + summaryStyle + '">📚 Data library members · ' + dataIds.length + '</summary>' +
        '<div style="padding:12px 14px;">' +
          '<div style="font-size:10px; color:#64748b; margin-bottom:8px;">Check data libraries to include — playbooks, risk rules, templates, prompts, etc. Bundle install/update walks both tools AND data libraries.</div>' +
          '<div style="max-height:300px; overflow-y:auto; border:1px solid #e2e8f0;">' +
            (allData.length === 0
              ? '<div style="padding:14px; font-size:10px; color:#94a3b8; text-align:center;">No data libraries in the manifest yet.</div>'
              : allData.map(function (d, idx) {
                  var checked = dataIds.indexOf(d.id) !== -1;
                  var stripe = idx % 2 === 0 ? "#fff" : "#f8fafc";
                  var lock = d.id.indexOf("_proprietary") !== -1 ? ' 🔒' : '';
                  return '<label style="display:flex; align-items:center; gap:8px; padding:6px 10px; background:' + stripe + '; border-bottom:1px solid #f1f5f9; cursor:pointer; font-size:11px;">' +
                    '<input type="checkbox" data-tas-bundle-data="' + _ebEsc(d.id) + '"' + (checked ? ' checked' : '') + ' style="cursor:pointer; margin:0;">' +
                    '<span style="font-weight:700; color:#0f172a;">' + _ebEsc(d.label || d.id) + lock + '</span>' +
                    '<span style="color:#94a3b8; font-family:ui-monospace,Consolas,monospace; font-size:10px;">' + _ebEsc(d.id) + '</span>' +
                  '</label>';
                }).join("")
            ) +
          '</div>' +
        '</div>' +
      '</details>' +
      // ─── Action buttons ─────────────────────────────────────────────────
      '<div style="display:flex; gap:8px; margin-top:12px;">' +
        '<button id="tasBundleSave" style="flex:1; padding:10px; font-size:11px; font-weight:800; background:linear-gradient(135deg,#16a34a,#15803d); color:#fff; border:none; cursor:pointer;">🚀 ' + (isNew ? "Create + push to manifest" : "Save + push to manifest") + '</button>' +
        '<button id="tasBundleCancel" style="flex:1; padding:10px; font-size:11px; font-weight:700; background:#fff; color:#64748b; border:1px solid #cbd5e1; cursor:pointer;">Cancel</button>' +
      '</div>' +
      '<div id="tasBundleStatus" style="font-size:10px; color:#64748b; margin-top:6px; min-height:14px;"></div>';
    content.innerHTML = html;
    document.getElementById("tasBundleBack").onclick = function () { _tasBundlesTab(content); };
    document.getElementById("tasBundleCancel").onclick = function () { _tasBundlesTab(content); };
    // Tool member checkbox handler
    content.querySelectorAll("[data-tas-bundle-member]").forEach(function (cb) {
      cb.onchange = function () {
        var id = cb.getAttribute("data-tas-bundle-member");
        var i = memberIds.indexOf(id);
        if (cb.checked && i === -1) memberIds.push(id);
        else if (!cb.checked && i !== -1) memberIds.splice(i, 1);
      };
    });
    // Data member checkbox handler
    content.querySelectorAll("[data-tas-bundle-data]").forEach(function (cb) {
      cb.onchange = function () {
        var id = cb.getAttribute("data-tas-bundle-data");
        var i = dataIds.indexOf(id);
        if (cb.checked && i === -1) dataIds.push(id);
        else if (!cb.checked && i !== -1) dataIds.splice(i, 1);
      };
    });
    document.getElementById("tasBundleSave").onclick = function () {
      var statusEl = document.getElementById("tasBundleStatus");
      function setStatus(msg) { statusEl.textContent = msg; }
      // Collect all fields
      if (isNew) {
        var idVal = document.getElementById("tasBundleId").value.trim();
        if (!idVal) { setStatus("❌ Bundle id required."); return; }
        if (idVal.indexOf("bundle_") !== 0) { setStatus("❌ Bundle id must start with 'bundle_'."); return; }
        bundle.id = idVal;
      }
      bundle.kind = "bundle";
      bundle.label = document.getElementById("tasBundleLabel").value.trim();
      bundle.icon = document.getElementById("tasBundleIcon").value.trim() || "📦";
      bundle.desc = document.getElementById("tasBundleDesc").value.trim();
      bundle.category = document.getElementById("tasBundleCategory").value.trim() || "Tools - ELI Core";
      // Audience: combine group checkboxes + custom tags
      var aud = [];
      document.querySelectorAll("[data-tas-bundle-group-cb]:checked").forEach(function (cb) {
        aud.push(cb.getAttribute("data-tas-bundle-group-cb"));
      });
      var customAudEl = document.getElementById("tasBundleAudienceCustom");
      if (customAudEl) {
        customAudEl.value.split(",").map(function (s) { return s.trim(); }).filter(Boolean).forEach(function (t) {
          if (aud.indexOf(t) === -1) aud.push(t);
        });
      }
      bundle.audience = aud;
      var emails = document.getElementById("tasBundleAudienceEmails").value.split(/\r?\n/).map(function (s) { return s.trim(); }).filter(Boolean);
      if (emails.length) bundle.audienceEmails = emails; else delete bundle.audienceEmails;
      var domains = document.getElementById("tasBundleAudienceEmailDomains").value.split(/\r?\n/).map(function (s) {
        var v = s.trim();
        if (v && v.charAt(0) !== "@") v = "@" + v;
        return v;
      }).filter(Boolean);
      if (domains.length) bundle.audienceEmailDomains = domains; else delete bundle.audienceEmailDomains;
      bundle.tools = memberIds.slice();
      if (dataIds.length) bundle.data = dataIds.slice(); else delete bundle.data;
      if (!bundle.label) { setStatus("❌ Label is required."); return; }
      if (!bundle.tools.length && !dataIds.length) { setStatus("❌ Pick at least one tool or data library."); return; }
      _tasPushBundle(content, manifest, manifestSha, bundle, isNew, setStatus);
    };
  }
  paint();
}

functions._tasPushBundle:
function _tasPushBundle(content, manifest, manifestSha, bundle, isNew, setStatus) {
  var pat = "";
  var repo = "apndrewn/eli-data";
  var branch = "main";
  try { pat = localStorage.getItem("eli_alp_pat") || ""; } catch (_) {}
  try { repo = localStorage.getItem("eli_alp_repo") || repo; } catch (_) {}
  try { branch = localStorage.getItem("eli_alp_branch") || branch; } catch (_) {}
  setStatus("Fetching latest manifest…");
  // Re-fetch manifest before write to minimize SHA-mismatch races. The
  // manifest in memory might be stale if another push happened since this
  // editor was opened.
  _tasGhGet(pat, repo, branch, "tools-manifest-v2.json").then(function (mfFile) {
    if (!mfFile || !mfFile.content) throw new Error("Manifest not found.");
    var b64 = String(mfFile.content).replace(/\s/g, "");
    var binStr = atob(b64);
    var bytes = new Uint8Array(binStr.length);
    for (var i = 0; i < binStr.length; i++) bytes[i] = binStr.charCodeAt(i);
    var fresh = JSON.parse(new TextDecoder("utf-8").decode(bytes));
    if (!fresh || !Array.isArray(fresh.tools)) throw new Error("Manifest has no tools[] array.");
    var existingIdx = -1;
    for (var i2 = 0; i2 < fresh.tools.length; i2++) {
      if (fresh.tools[i2] && fresh.tools[i2].id === bundle.id) { existingIdx = i2; break; }
    }
    bundle.lastUpdated = new Date().toISOString();
    bundle.changelog = (isNew ? "Created" : "Updated") + " bundle via TAS · " + bundle.tools.length + " member" + (bundle.tools.length === 1 ? "" : "s");
    if (existingIdx === -1) {
      fresh.tools.push(bundle);
    } else {
      fresh.tools[existingIdx] = bundle;
    }
    fresh.lastUpdated = new Date().toISOString();
    setStatus("Uploading manifest…");
    var newStr = JSON.stringify(fresh, null, 2);
    // After successful PUT, refresh the local bundle cache so subsequent
    // renders (Tools tab, Tool Manager) see the new state without waiting
    // for an update check. The `fresh` object is the post-push manifest.
    return _tasGhPut(pat, repo, branch, "tools-manifest-v2.json", newStr,
      "[TAS] " + (isNew ? "create" : "update") + " bundle " + bundle.id, mfFile.sha).then(function () {
        try {
          var refreshedBundles = (fresh.tools || []).filter(function (e) { return e && e.kind === "bundle"; });
          window._eliBundles = refreshedBundles;
          localStorage.setItem("eli_bundles", JSON.stringify(refreshedBundles));
        } catch (_) {}
      });
  }).then(function () {
    setStatus("✓ Pushed.");
    if (typeof showToast === "function") showToast("✓ Bundle " + (isNew ? "created" : "updated") + ": " + (bundle.label || bundle.id), "success");
    setTimeout(function () { _tasBundlesTab(content); }, 600);
  }).catch(function (e) {
    setStatus("❌ " + (e && e.message ? e.message : String(e)));
  });
}

functions._tasDeleteBundle:
function _tasDeleteBundle(content, manifest, manifestSha, bundleId) {
  var pat = "";
  var repo = "apndrewn/eli-data";
  var branch = "main";
  try { pat = localStorage.getItem("eli_alp_pat") || ""; } catch (_) {}
  try { repo = localStorage.getItem("eli_alp_repo") || repo; } catch (_) {}
  try { branch = localStorage.getItem("eli_alp_branch") || branch; } catch (_) {}
  showToast("Removing bundle…", "info");
  _tasGhGet(pat, repo, branch, "tools-manifest-v2.json").then(function (mfFile) {
    if (!mfFile || !mfFile.content) throw new Error("Manifest not found.");
    var b64 = String(mfFile.content).replace(/\s/g, "");
    var binStr = atob(b64);
    var bytes = new Uint8Array(binStr.length);
    for (var i = 0; i < binStr.length; i++) bytes[i] = binStr.charCodeAt(i);
    var fresh = JSON.parse(new TextDecoder("utf-8").decode(bytes));
    fresh.tools = (fresh.tools || []).filter(function (e) { return !(e && e.id === bundleId); });
    fresh.lastUpdated = new Date().toISOString();
    var newStr = JSON.stringify(fresh, null, 2);
    return _tasGhPut(pat, repo, branch, "tools-manifest-v2.json", newStr,
      "[TAS] delete bundle " + bundleId, mfFile.sha).then(function () {
        // Refresh local cache so the deleted bundle vanishes from Tools tab
        // / Tool Manager without a force-check round-trip.
        try {
          var refreshedBundles = (fresh.tools || []).filter(function (e) { return e && e.kind === "bundle"; });
          window._eliBundles = refreshedBundles;
          localStorage.setItem("eli_bundles", JSON.stringify(refreshedBundles));
        } catch (_) {}
      });
  }).then(function () {
    showToast("✓ Bundle deleted: " + bundleId, "success");
    _tasBundlesTab(content);
  }).catch(function (e) {
    showToast("❌ " + (e && e.message ? e.message : String(e)), "error");
  });
}

functions._tasDataTab:
function _tasDataTab(content) {
  var pat = "";
  var repo = "apndrewn/eli-data";
  var branch = "main";
  try { pat = localStorage.getItem("eli_alp_pat") || ""; } catch (_) {}
  try { repo = localStorage.getItem("eli_alp_repo") || repo; } catch (_) {}
  try { branch = localStorage.getItem("eli_alp_branch") || branch; } catch (_) {}
  if (!pat) {
    content.innerHTML =
      '<div style="padding:24px; text-align:center; font-size:11px; color:#92400e; background:#fffbeb; border:1px solid #fde68a;">' +
      '⚠️ No GitHub PAT set. Open <strong>Admin Library Publisher</strong> first and configure your PAT — Data audience editing pushes manifest changes.' +
      '</div>';
    return;
  }
  content.innerHTML = '<div style="padding:14px; text-align:center; font-size:11px; color:#94a3b8;">Loading manifest…</div>';
  _tasGhGet(pat, repo, branch, "tools-manifest-v2.json").then(function (mfFile) {
    if (!mfFile || !mfFile.content) throw new Error("Manifest not found.");
    var b64 = String(mfFile.content).replace(/\s/g, "");
    var binStr = atob(b64);
    var bytes = new Uint8Array(binStr.length);
    for (var i = 0; i < binStr.length; i++) bytes[i] = binStr.charCodeAt(i);
    var manifest = JSON.parse(new TextDecoder("utf-8").decode(bytes));
    var allEntries = Array.isArray(manifest.tools) ? manifest.tools : [];
    var dataEntries = allEntries.filter(function (e) { return e && e.kind === "data"; });
    var bundles = allEntries.filter(function (e) { return e && e.kind === "bundle"; });
    _tasRenderDataList(content, manifest, mfFile.sha, dataEntries, bundles);
  }).catch(function (e) {
    content.innerHTML =
      '<div style="padding:24px; text-align:center; font-size:11px; color:#991b1b; background:#fef2f2; border:1px solid #fca5a5;">' +
      '❌ Couldn\'t load manifest: ' + _ebEsc(e && e.message ? e.message : String(e)) +
      '</div>';
  });
}

functions._tasRenderDataList:
function _tasRenderDataList(content, manifest, manifestSha, dataEntries, bundles) {
  bundles = bundles || [];
  var headerHtml =
    '<div style="font-size:11px; color:#64748b; margin-bottom:10px; line-height:1.5;">' +
    '<strong style="color:#0f172a;">' + dataEntries.length + ' data librar' + (dataEntries.length === 1 ? 'y' : 'ies') + '.</strong> ' +
    'Click a row to edit audience (who can see / install it). ' +
    '<strong>Content + version</strong> is pushed via Admin Library Publisher; this tab only manages metadata.' +
    '</div>';
  if (dataEntries.length === 0) {
    content.innerHTML = headerHtml +
      '<div style="padding:24px; text-align:center; font-size:11px; color:#64748b; background:#f8fafc; border:1px dashed #cbd5e1;">No data libraries in the manifest.</div>';
    return;
  }
  // Build data → bundles map (a data lib can be in multiple bundles).
  var dataToBundles = {};
  bundles.forEach(function (b) {
    if (!Array.isArray(b.data)) return;
    b.data.forEach(function (id) {
      if (!dataToBundles[id]) dataToBundles[id] = [];
      dataToBundles[id].push(b);
    });
  });
  function renderDataRow(d, idx) {
    var stripe = idx % 2 === 0 ? "#fff" : "#f8fafc";
    var lab = d.label || d.id;
    var aud = d.audience && d.audience.length ? d.audience.join(", ") : "(no tags — visible to all)";
    var emails = (d.audienceEmails || []).length;
    var domains = (d.audienceEmailDomains || []).length;
    var locked = d.id.indexOf("_proprietary") !== -1;
    var ver = d.version != null ? String(d.version) : "?";
    var inBundles = dataToBundles[d.id] || [];
    var bundleChips = inBundles.map(function (b) {
      return '<span style="display:inline-block; padding:2px 7px; font-size:9px; font-weight:700; background:#faf5ff; color:#6b21a8; border:1px solid #c4b5fd;" title="Member of bundle: ' + _ebEsc(b.id) + '">📦 ' + _ebEsc(b.label || b.id) + '</span>';
    }).join("");
    return (
      '<div data-tas-data-row="' + _ebEsc(d.id) + '" style="background:' + stripe + '; border:1px solid #e2e8f0; padding:10px 12px; margin-bottom:5px;">' +
      '<div style="display:flex; justify-content:space-between; align-items:flex-start; gap:8px;">' +
      '<div style="flex:1; min-width:0; cursor:pointer;" data-tas-data-edit="' + _ebEsc(d.id) + '">' +
      '<div style="font-size:13px; font-weight:700; color:#0f172a;">📚 ' + _ebEsc(lab) + (locked ? ' 🔒' : '') + ' <span style="font-size:10px; font-weight:500; color:#1565c0;">(v' + _ebEsc(ver) + ')</span></div>' +
      '<div style="font-size:10px; color:#64748b; margin-top:2px;">id: <code>' + _ebEsc(d.id) + '</code> · ' + _ebEsc(d.filename || "(no file)") + '</div>' +
      '<div style="font-size:10px; color:#64748b; margin-top:2px;">audience: ' + _ebEsc(aud) + (emails ? ' · ' + emails + ' email' + (emails === 1 ? '' : 's') : '') + (domains ? ' · ' + domains + ' domain' + (domains === 1 ? '' : 's') : '') + '</div>' +
      (bundleChips ? '<div style="display:flex; gap:5px; margin-top:5px; flex-wrap:wrap;">' + bundleChips + '</div>' : '') +
      '</div>' +
      '<button data-tas-data-edit-btn="' + _ebEsc(d.id) + '" style="padding:5px 10px; font-size:10px; cursor:pointer; background:#1565c0; color:#fff; border:none; font-weight:700;">📝 Edit</button>' +
      '</div>' +
      '</div>'
    );
  }
  // Group data into bundles + standalone (not in any bundle)
  var standaloneData = dataEntries.filter(function (d) { return !dataToBundles[d.id]; });
  var html = headerHtml;
  // ─── Bundles section ─────────────────────────────────────────────────
  var bundlesWithData = bundles.filter(function (b) {
    return Array.isArray(b.data) && b.data.length > 0;
  });
  if (bundlesWithData.length > 0) {
    bundlesWithData.sort(function (a, b) { return (a.label || a.id || "").localeCompare(b.label || b.id || ""); });
    html += '<div style="margin-top:6px; padding:6px 10px; background:linear-gradient(135deg,#4c1d95,#5b21b6); color:#fff; font-size:10px; font-weight:800; text-transform:uppercase; letter-spacing:0.5px;">' +
      '📦 Bundles with data libraries (' + bundlesWithData.length + ')' +
      '</div>';
    bundlesWithData.forEach(function (b) {
      var members = dataEntries.filter(function (d) {
        return Array.isArray(b.data) && b.data.indexOf(d.id) !== -1;
      });
      members.sort(function (x, y) { return (x.label || x.id || "").localeCompare(y.label || y.id || ""); });
      var bIc = b.icon || "📦";
      var bLab = b.label || b.id;
      var bDesc = b.desc || "";
      var bKey = "eli_tas_data_bundle_" + (b.id || "x").replace(/\W+/g, "_");
      var collapsed = true;
      try {
        var stored = localStorage.getItem(bKey);
        if (stored === "0") collapsed = false;
      } catch (_) {}
      html += '<details data-tas-data-bundle-key="' + _ebEsc(bKey) + '"' + (collapsed ? '' : ' open') + ' style="margin-bottom:8px; border:1px solid #c4b5fd; background:#faf5ff;">';
      html += '<summary style="cursor:pointer; padding:10px 12px; user-select:none; list-style:none; display:flex; justify-content:space-between; align-items:flex-start; gap:8px;">' +
        '<div style="flex:1; min-width:0;">' +
          '<div style="font-size:13px; font-weight:800; color:#4c1d95;">' + bIc + ' ' + _ebEsc(bLab) + ' <span style="font-size:10px; color:#7c3aed; font-weight:600;">(' + members.length + ' data lib' + (members.length === 1 ? '' : 's') + ')</span></div>' +
          (bDesc ? '<div style="font-size:10px; color:#6b21a8; margin-top:2px;">' + _ebEsc(bDesc) + '</div>' : '') +
        '</div>' +
        '<button data-tas-data-bundle-edit="' + _ebEsc(b.id) + '" title="Edit bundle metadata + members in the Bundles tab" style="padding:5px 10px; font-size:10px; cursor:pointer; background:#fff; color:#6b21a8; border:1px solid #c4b5fd; font-weight:700; flex-shrink:0;">⚙️ Edit bundle</button>' +
      '</summary>';
      html += '<div style="padding:8px;">';
      members.forEach(function (d, idx) { html += renderDataRow(d, idx); });
      html += '</div></details>';
    });
  }
  // ─── Standalone data libraries (not in any bundle) ───────────────────
  if (standaloneData.length > 0) {
    standaloneData.sort(function (a, b) { return (a.label || a.id || "").localeCompare(b.label || b.id || ""); });
    html += '<div style="margin-top:14px; padding:6px 10px; background:linear-gradient(135deg,#0f172a,#1e293b); color:#fff; font-size:10px; font-weight:800; text-transform:uppercase; letter-spacing:0.5px;">' +
      (bundlesWithData.length ? '🧩 Standalone data libraries (' + standaloneData.length + ')' : '🧩 Data libraries (' + standaloneData.length + ')') +
      '</div>';
    html += '<div style="padding:8px 0;">';
    standaloneData.forEach(function (d, idx) { html += renderDataRow(d, idx); });
    html += '</div>';
  }
  content.innerHTML = html;
  function findData(id) { return dataEntries.filter(function (d) { return d.id === id; })[0]; }
  function openEdit(id) {
    var d = findData(id);
    if (!d) return;
    _tasOpenDataEditor(content, manifest, manifestSha, JSON.parse(JSON.stringify(d)));
  }
  content.querySelectorAll("[data-tas-data-edit]").forEach(function (el) {
    el.onclick = function (e) { e.stopPropagation(); openEdit(el.getAttribute("data-tas-data-edit")); };
  });
  content.querySelectorAll("[data-tas-data-edit-btn]").forEach(function (el) {
    el.onclick = function (e) { e.stopPropagation(); openEdit(el.getAttribute("data-tas-data-edit-btn")); };
  });
  // "Edit bundle" jump (mirrors Tools tab) — find Bundles tab button by
  // exact text match on a leaf div in #output and click it.
  content.querySelectorAll("[data-tas-data-bundle-edit]").forEach(function (b) {
    b.onclick = function (e) {
      e.preventDefault();
      e.stopPropagation();
      try { window._tasJumpToBundleId = b.getAttribute("data-tas-data-bundle-edit"); } catch (_) {}
      var allDivs = document.querySelectorAll("#output div");
      for (var i = 0; i < allDivs.length; i++) {
        var d = allDivs[i];
        if (d.children.length !== 0) continue;
        if ((d.textContent || "").trim() === "📦 Bundles") {
          d.click();
          return;
        }
      }
    };
  });
  // Per-bundle collapse persistence
  content.querySelectorAll("details[data-tas-data-bundle-key]").forEach(function (d) {
    d.addEventListener("toggle", function () {
      var key = d.getAttribute("data-tas-data-bundle-key");
      try { localStorage.setItem(key, d.open ? "0" : "1"); } catch (_) {}
    });
  });
}

functions._tasOpenDataEditor:
function _tasOpenDataEditor(content, manifest, manifestSha, dataEntry) {
  var KNOWN_GROUPS = ["all", "External Innovation", "Commercial", "Litigation", "Patents"];
  var sectionStyle = "background:#fff; border:1px solid #e2e8f0; border-top:none;";
  var summaryStyle = "cursor:pointer; padding:10px 14px; background:#f8fafc; font-size:11px; font-weight:800; color:#0f172a; text-transform:uppercase; letter-spacing:0.5px; user-select:none; list-style:none; border-bottom:1px solid #e2e8f0;";
  var current = Array.isArray(dataEntry.audience) ? dataEntry.audience : [];
  var customTags = current.filter(function (t) { return KNOWN_GROUPS.indexOf(t) === -1; });
  var html =
    '<button id="tasDataBack" style="margin-bottom:8px; padding:4px 10px; font-size:10px; cursor:pointer; background:#fff; border:1px solid #cbd5e1; color:#64748b;">← Back to data list</button>' +
    '<div style="background:linear-gradient(135deg,#1e3a8a,#1e40af); color:#fff; padding:12px 14px; border:1px solid #e2e8f0;">' +
      '<div style="font-size:14px; font-weight:800;">📚 ' + _ebEsc(dataEntry.label || dataEntry.id) + '</div>' +
      '<div style="font-size:10px; color:#bfdbfe; margin-top:3px;">id: <code style="color:#dbeafe;">' + _ebEsc(dataEntry.id) + '</code> · v' + _ebEsc(String(dataEntry.version || "?")) + ' · file: <code style="color:#dbeafe;">' + _ebEsc(dataEntry.filename || "(none)") + '</code></div>' +
    '</div>' +
    // ─── Identity ──────────────────────────────────────────────────────
    '<details open style="' + sectionStyle + '">' +
      '<summary style="' + summaryStyle + '">🪪 Identity</summary>' +
      '<div style="padding:12px 14px;">' +
        _tasField("tasDataLabel", "Label (display name)", dataEntry.label || "", "text") +
        _tasField("tasDataCategory", "Category", dataEntry.category || "Data", "text") +
        '<div style="margin-top:8px; padding:8px 10px; background:#f8fafc; border:1px solid #e2e8f0; font-size:10.5px; color:#64748b; line-height:1.5;">' +
          '<strong>Note:</strong> id, filename, version, and content are managed by Admin Library Publisher. This tab only edits metadata + audience.' +
        '</div>' +
      '</div>' +
    '</details>' +
    // ─── Audience ──────────────────────────────────────────────────────
    '<details open style="' + sectionStyle + '">' +
      '<summary style="' + summaryStyle + '">👥 Audience (who can see / install this data library)</summary>' +
      '<div style="padding:12px 14px;">' +
        '<label style="display:block; font-size:10px; font-weight:700; color:#64748b; margin:0 0 3px 0; text-transform:uppercase; letter-spacing:0.3px;">Groups</label>' +
        '<div style="display:grid; grid-template-columns:1fr 1fr; gap:4px 12px; padding:8px 10px; background:#f8fafc; border:1px solid #e2e8f0;">' +
          KNOWN_GROUPS.map(function (g) {
            var checked = current.indexOf(g) !== -1;
            var label = g === "all" ? "🌐 All (everyone)" : g;
            return '<label style="display:flex; align-items:center; gap:6px; font-size:11px; color:#475569; cursor:pointer;">' +
              '<input type="checkbox" data-tas-data-group-cb="' + _ebEsc(g) + '"' + (checked ? ' checked' : '') + ' style="margin:0; cursor:pointer;">' +
              _ebEsc(label) +
            '</label>';
          }).join("") +
        '</div>' +
        '<label style="display:block; font-size:10px; font-weight:700; color:#64748b; margin:8px 0 3px 0; text-transform:uppercase; letter-spacing:0.3px;">Other tags (comma-separated, custom audiences)</label>' +
        '<input id="tasDataAudienceCustom" type="text" value="' + _ebEsc(customTags.join(", ")) + '" style="width:100%; padding:6px 8px; font-size:11px; border:1px solid #cbd5e1; box-sizing:border-box;">' +
        '<label style="display:block; font-size:10px; font-weight:700; color:#64748b; margin:8px 0 3px 0; text-transform:uppercase; letter-spacing:0.3px;">Audience emails (one per line)</label>' +
        '<textarea id="tasDataAudienceEmails" placeholder="someone@colpal.com" style="width:100%; min-height:50px; padding:6px 8px; font-size:11px; border:1px solid #cbd5e1; box-sizing:border-box; font-family:ui-monospace,Consolas,monospace;">' + _ebEsc((Array.isArray(dataEntry.audienceEmails) ? dataEntry.audienceEmails.join("\n") : "")) + '</textarea>' +
        '<label style="display:block; font-size:10px; font-weight:700; color:#64748b; margin:8px 0 3px 0; text-transform:uppercase; letter-spacing:0.3px;">Audience email domains (one per line)</label>' +
        '<textarea id="tasDataAudienceEmailDomains" placeholder="@colpal.com" style="width:100%; min-height:50px; padding:6px 8px; font-size:11px; border:1px solid #cbd5e1; box-sizing:border-box; font-family:ui-monospace,Consolas,monospace;">' + _ebEsc((Array.isArray(dataEntry.audienceEmailDomains) ? dataEntry.audienceEmailDomains.join("\n") : "")) + '</textarea>' +
      '</div>' +
    '</details>' +
    '<div style="display:flex; gap:8px; margin-top:12px;">' +
      '<button id="tasDataSave" style="flex:1; padding:10px; font-size:11px; font-weight:800; background:linear-gradient(135deg,#1565c0,#0d47a1); color:#fff; border:none; cursor:pointer;">🚀 Save + push to manifest</button>' +
      '<button id="tasDataCancel" style="flex:1; padding:10px; font-size:11px; font-weight:700; background:#fff; color:#64748b; border:1px solid #cbd5e1; cursor:pointer;">Cancel</button>' +
    '</div>' +
    '<div id="tasDataStatus" style="font-size:10px; color:#64748b; margin-top:6px; min-height:14px;"></div>';
  content.innerHTML = html;
  document.getElementById("tasDataBack").onclick = function () { _tasDataTab(content); };
  document.getElementById("tasDataCancel").onclick = function () { _tasDataTab(content); };
  document.getElementById("tasDataSave").onclick = function () {
    var statusEl = document.getElementById("tasDataStatus");
    function setStatus(msg) { statusEl.textContent = msg; }
    var labelVal = document.getElementById("tasDataLabel").value.trim();
    if (labelVal) dataEntry.label = labelVal;
    var catVal = document.getElementById("tasDataCategory").value.trim();
    if (catVal) dataEntry.category = catVal;
    // Audience: combine groups + custom tags
    var aud = [];
    document.querySelectorAll("[data-tas-data-group-cb]:checked").forEach(function (cb) {
      aud.push(cb.getAttribute("data-tas-data-group-cb"));
    });
    var customEl = document.getElementById("tasDataAudienceCustom");
    if (customEl) {
      customEl.value.split(",").map(function (s) { return s.trim(); }).filter(Boolean).forEach(function (t) {
        if (aud.indexOf(t) === -1) aud.push(t);
      });
    }
    if (aud.length) dataEntry.audience = aud; else delete dataEntry.audience;
    var emails = document.getElementById("tasDataAudienceEmails").value.split(/\r?\n/).map(function (s) { return s.trim(); }).filter(Boolean);
    if (emails.length) dataEntry.audienceEmails = emails; else delete dataEntry.audienceEmails;
    var domains = document.getElementById("tasDataAudienceEmailDomains").value.split(/\r?\n/).map(function (s) {
      var v = s.trim();
      if (v && v.charAt(0) !== "@") v = "@" + v;
      return v;
    }).filter(Boolean);
    if (domains.length) dataEntry.audienceEmailDomains = domains; else delete dataEntry.audienceEmailDomains;
    _tasPushDataEntry(content, manifest, manifestSha, dataEntry, setStatus);
  };
}

functions._tasPushDataEntry:
function _tasPushDataEntry(content, manifest, manifestSha, dataEntry, setStatus) {
  var pat = "";
  var repo = "apndrewn/eli-data";
  var branch = "main";
  try { pat = localStorage.getItem("eli_alp_pat") || ""; } catch (_) {}
  try { repo = localStorage.getItem("eli_alp_repo") || repo; } catch (_) {}
  try { branch = localStorage.getItem("eli_alp_branch") || branch; } catch (_) {}
  setStatus("Fetching latest manifest…");
  _tasGhGet(pat, repo, branch, "tools-manifest-v2.json").then(function (mfFile) {
    if (!mfFile || !mfFile.content) throw new Error("Manifest not found.");
    var b64 = String(mfFile.content).replace(/\s/g, "");
    var binStr = atob(b64);
    var bytes = new Uint8Array(binStr.length);
    for (var i = 0; i < binStr.length; i++) bytes[i] = binStr.charCodeAt(i);
    var fresh = JSON.parse(new TextDecoder("utf-8").decode(bytes));
    var idx = fresh.tools.findIndex(function (e) { return e && e.id === dataEntry.id; });
    if (idx === -1) throw new Error("Data entry not found in manifest: " + dataEntry.id);
    // Merge our metadata-only changes into the fresh entry (preserves
    // version/lastUpdated/size set by ALP's content push).
    var freshEntry = fresh.tools[idx];
    freshEntry.label = dataEntry.label;
    freshEntry.category = dataEntry.category;
    if (dataEntry.audience) freshEntry.audience = dataEntry.audience; else delete freshEntry.audience;
    if (dataEntry.audienceEmails) freshEntry.audienceEmails = dataEntry.audienceEmails; else delete freshEntry.audienceEmails;
    if (dataEntry.audienceEmailDomains) freshEntry.audienceEmailDomains = dataEntry.audienceEmailDomains; else delete freshEntry.audienceEmailDomains;
    fresh.lastUpdated = new Date().toISOString();
    setStatus("Uploading manifest…");
    var newStr = JSON.stringify(fresh, null, 2);
    return _tasGhPut(pat, repo, branch, "tools-manifest-v2.json", newStr,
      "[TAS] data " + dataEntry.id + ": metadata + audience update", mfFile.sha);
  }).then(function () {
    setStatus("✓ Pushed.");
    if (typeof showToast === "function") showToast("✓ Data library updated: " + (dataEntry.label || dataEntry.id), "success");
    setTimeout(function () { _tasDataTab(content); }, 600);
  }).catch(function (e) {
    setStatus("❌ " + (e && e.message ? e.message : String(e)));
  });
}

functions._tasValidateSource:
function _tasValidateSource(src) {
  if (!src || !src.trim()) return "Empty source";
  try { new Function("return (\n" + src + "\n);"); return null; }
  catch (e) { return e && e.message ? e.message : "Unknown syntax error"; }
}
// Form-field helper used across TAS edit cards. Renders a labelled input.

functions._tasField:
function _tasField(id, label, value, type) {
  return '<label style="display:block; font-size:10px; font-weight:700; color:#64748b; margin:8px 0 3px 0; text-transform:uppercase; letter-spacing:0.3px;">' + _ebEsc(label) + '</label>' +
    '<input id="' + id + '" type="' + (type || "text") + '" value="' + _ebEsc(String(value)) + '" style="width:100%; padding:6px 8px; font-size:11px; border:1px solid #cbd5e1; box-sizing:border-box;">';
}

functions._tasSaveCatalogRow:
function _tasSaveCatalogRow(row) {
  return loadFeatureData(STORE_CATALOG).then(function (rows) {
    rows = rows || [];
    var byId = {};
    rows.forEach(function (r) { if (r && r.id) byId[r.id] = r; });
    byId[row.id] = row;
    var newRows = Object.keys(byId).map(function (k) { return byId[k]; });
    return saveFeatureData(STORE_CATALOG, newRows);
  }).then(function () {
    // Mirror the edit back into the source tool's tool.catalog block in
    // STORE_JSON_TOOLS so TAS Push (which reads from json_tools) sends the
    // updated tile. Without this, catalog edits would be local-only and
    // would never propagate via push — the source-of-truth split between
    // STORE_CATALOG and tool.catalog would silently diverge.
    var src = String(row && row.source || "");
    if (src.indexOf("tool:") !== 0) return;
    var toolId = src.substring("tool:".length);
    return loadFeatureData(STORE_JSON_TOOLS).then(function (toolRows) {
      toolRows = toolRows || [];
      var idx = -1;
      for (var i = 0; i < toolRows.length; i++) {
        if (toolRows[i] && toolRows[i].id === toolId) { idx = i; break; }
      }
      if (idx === -1) return; // tool no longer in IDB — nothing to mirror
      // Strip the local-only `source` marker before stamping into
      // tool.catalog (it gets re-added by the sync on next install).
      var catalogPayload = {};
      Object.keys(row).forEach(function (k) {
        if (k === "source" || k === "userOverride") return;
        catalogPayload[k] = row[k];
      });
      toolRows[idx].catalog = catalogPayload;
      return saveFeatureData(STORE_JSON_TOOLS, toolRows);
    });
  }).then(function () {
    if (typeof _eliInvalidateCatalogCache === "function") _eliInvalidateCatalogCache();
    if (typeof _eliEnsureCatalogLoaded === "function") {
      return _eliEnsureCatalogLoaded().then(function () {
        try { if (typeof window.refreshDashboardGrid === "function") window.refreshDashboardGrid(); } catch (_) {}
      });
    }
  });
}

functions._tasSaveTool:
function _tasSaveTool(tool) {
  return loadFeatureData(STORE_JSON_TOOLS).then(function (rows) {
    rows = rows || [];
    var byId = {};
    rows.forEach(function (r) { if (r && r.id) byId[r.id] = r; });
    // Auto-snapshot the PREVIOUS state of this tool before overwriting (history
    // tab can roll back). No-op for brand-new tools.
    if (byId[tool.id] && typeof _tasSnapshotTool === "function") {
      _tasSnapshotTool(byId[tool.id]);
    }
    byId[tool.id] = tool;
    var newRows = Object.keys(byId).map(function (k) { return byId[k]; });
    return saveFeatureData(STORE_JSON_TOOLS, newRows);
  }).then(function () {
    // Re-eval the tool's functions immediately so changes take effect without reload.
    try {
      if (tool.functions && typeof tool.functions === "object") {
        Object.keys(tool.functions).forEach(function (fnName) {
          var src = tool.functions[fnName];
          if (typeof src === "string" && src.length) {
            window[fnName] = new Function("return (\n" + src + "\n);")();
          }
        });
      }
    } catch (e) { console.warn("[TAS] re-eval after save failed:", e); }
    // Sync catalog in case the tool's catalog block changed (it's the same row).
    if (typeof _dataHubSyncToolsToCatalog === "function") return _dataHubSyncToolsToCatalog();
  });
}

functions._tasNewChat:
function _tasNewChat() {
  return { messages: [] }; // { role: "user"|"assistant", content: string }
}

// Append a turn to a chat object (messages = system+user+assistant turns).

functions._tasChatAppend:
function _tasChatAppend(chat, role, content) {
  if (!chat || !chat.messages) return;
  chat.messages.push({ role: role, content: String(content || "") });
}

// Render the chat transcript into a host element (scrollable, auto-scroll).

functions._tasRenderChat:
function _tasRenderChat(chat, host) {
  if (!host) return;
  host.innerHTML = chat.messages.map(function (m) {
    var bg = m.role === "user" ? "#e0f2fe" : "#f1f5f9";
    var color = m.role === "user" ? "#0c4a6e" : "#334155";
    var lbl = m.role === "user" ? "YOU" : "AI";
    var lblColor = m.role === "user" ? "#0369a1" : "#64748b";
    return (
      '<div style="margin-bottom:8px;">' +
      '<div style="font-size:9px; font-weight:800; color:' + lblColor + '; letter-spacing:0.6px; margin-bottom:2px;">' + lbl + '</div>' +
      '<div style="background:' + bg + '; color:' + color + '; padding:8px 10px; font-size:11px; line-height:1.5; white-space:pre-wrap; word-wrap:break-word; border-left:2px solid ' + lblColor + ';">' +
      _ebEsc(m.content) +
      '</div>' +
      '</div>'
    );
  }).join("");
  host.scrollTop = host.scrollHeight;
}

// Build a Gemini prompt that combines system instructions + chat transcript.

functions._tasBuildChatPrompt:
function _tasBuildChatPrompt(systemPrompt, chat) {
  var transcript = chat.messages.map(function (m) {
    return (m.role === "user" ? "USER: " : "ASSISTANT: ") + m.content;
  }).join("\n\n");
  return systemPrompt + "\n\n=== CONVERSATION SO FAR ===\n" + transcript + "\n\nASSISTANT:";
}

// Strip code fences and language hints from AI output.

functions._tasCleanCode:
function _tasCleanCode(s) {
  return String(s || "")
    .replace(/```(?:javascript|js|json)?\s*/gi, "")
    .replace(/```/g, "")
    .trim();
}

// Try to extract a JSON object from AI output. Returns null on failure.

functions._tasExtractJson:
function _tasExtractJson(s) {
  if (!s) return null;
  var t = _tasCleanCode(s);
  // Find first { and last } to handle prose around JSON.
  var first = t.indexOf("{"), last = t.lastIndexOf("}");
  if (first === -1 || last === -1 || last <= first) return null;
  try { return JSON.parse(t.substring(first, last + 1)); }
  catch (_) { return null; }
}

// Snapshot a tool to localStorage history (max 10 entries per tool).

functions._tasSnapshotTool:
function _tasSnapshotTool(tool) {
  if (!tool || !tool.id) return;
  try {
    var key = "_tas_history_" + tool.id;
    var arr = [];
    try { arr = JSON.parse(localStorage.getItem(key) || "[]"); } catch (_) { arr = []; }
    arr.unshift({ at: Date.now(), version: Number(tool.__version) || 0, tool: JSON.parse(JSON.stringify(tool)) });
    if (arr.length > 10) arr = arr.slice(0, 10);
    localStorage.setItem(key, JSON.stringify(arr));
  } catch (e) { console.warn("[TAS] snapshot failed:", e); }
}

functions._tasGetHistory:
function _tasGetHistory(toolId) {
  try { return JSON.parse(localStorage.getItem("_tas_history_" + toolId) || "[]"); }
  catch (_) { return []; }
}

// Lightweight JS beautifier: when AI returns minified single-line code, this
// re-introduces newlines and 2-space indentation. Not a full pretty-printer —
// good enough to make the source readable in the textarea.

functions._tasBeautifyJs:
function _tasBeautifyJs(src) {
  if (!src || typeof src !== "string") return src;
  // If the source already has multiple lines, leave it alone.
  var nlCount = (src.match(/\n/g) || []).length;
  var totalLen = src.length;
  if (nlCount > 0 && nlCount > totalLen / 200) return src; // already reasonably formatted
  // Strip carriage returns, normalize whitespace inside lines.
  var s = src.replace(/\r/g, "");
  // Insert newlines after structural punctuation that's NOT inside a string or comment.
  // Walk char by char tracking string/comment state.
  var out = "";
  var i = 0, n = s.length;
  var inSL = false, inML = false, inStr = false, strCh = "";
  while (i < n) {
    var ch = s[i], next = s[i + 1];
    if (inSL) { out += ch; if (ch === "\n") inSL = false; i++; continue; }
    if (inML) { out += ch; if (ch === "*" && next === "/") { out += next; i += 2; inML = false; continue; } i++; continue; }
    if (inStr) {
      out += ch;
      if (ch === "\\" && i + 1 < n) { out += s[i + 1]; i += 2; continue; }
      if (ch === strCh) inStr = false;
      i++; continue;
    }
    if (ch === "/" && next === "/") { inSL = true; out += ch; i++; continue; }
    if (ch === "/" && next === "*") { inML = true; out += ch; i++; continue; }
    if (ch === '"' || ch === "'" || ch === "`") { inStr = true; strCh = ch; out += ch; i++; continue; }
    if (ch === "{") { out += "{\n"; i++; continue; }
    if (ch === "}") { out += "\n}"; i++; if (s[i] && s[i] !== "\n" && s[i] !== ";" && s[i] !== "," && s[i] !== ")") out += "\n"; continue; }
    if (ch === ";") { out += ";\n"; i++; continue; }
    out += ch; i++;
  }
  // Collapse runs of blank lines.
  out = out.replace(/\n{3,}/g, "\n\n");
  // Re-indent based on brace depth.
  var lines = out.split("\n");
  var depth = 0;
  var indented = lines.map(function (ln) {
    var trimmed = ln.replace(/^\s+/, "");
    if (trimmed.charAt(0) === "}") depth = Math.max(0, depth - 1);
    var pad = "";
    for (var k = 0; k < depth; k++) pad += "  ";
    var result = pad + trimmed;
    var opens = (trimmed.match(/{/g) || []).length;
    var closes = (trimmed.match(/}/g) || []).length;
    depth += opens - closes;
    if (depth < 0) depth = 0;
    return result;
  });
  return indented.join("\n").replace(/\s+$/g, "") + "\n";
}

functions._tasAiCreateTab:
function _tasAiCreateTab(content) {
  // Per-mount state.
