      if (obj.defaultEnabled === undefined) obj.defaultEnabled = true;
      if (!obj.catalog) obj.catalog = { id: "app_" + obj.id, icon: "🧩", title: obj.label || obj.id, desc: "", action: "" };
      if (!obj.catalog.id) obj.catalog.id = "app_" + obj.id;
