    var fns = Object.keys(draft.functions || {});
    if (fns.length) draft.functions[fns[0]] = srcArea.value;
    var firstFn = fns[0];
    var firstSrc = firstFn ? draft.functions[firstFn] : "";
    var err = _tasValidateSource(firstSrc);
    if (err) { showToast("❌ Won't save — syntax error: " + err, "error"); return; }
    _tasSnapshotTool(draft); // pre-save snapshot (a fresh tool will have empty history but consistent flow)
    _tasSaveTool(draft).then(function () {
      showToast("✓ Installed " + draft.id + " (v" + draft.__version + ").", "success");
      // Also persist as a catalog row so it shows on the dashboard.
      if (draft.catalog && typeof _tasSaveCatalogRow === "function") {
        _tasSaveCatalogRow(draft.catalog).catch(function () {});
      }
    });
  };

  // initial empty chat hint
  chatHost.innerHTML = '<div style="font-size:10px; color:#94a3b8; text-align:center; padding:18px;">Describe a tool you want — the AI will ask follow-ups, then emit a full JSON tool.</div>';
}

functions._tasAiFixTab:
function _tasAiFixTab(content) {
  var chat = _tasNewChat();
  var selectedTool = null;
  var selectedFn = null;
  var originalSrc = "";
  var proposedSrc = "";
  content.innerHTML = '<div style="padding:14px; text-align:center; font-size:11px; color:#94a3b8;">Loading tools…</div>';

  loadFeatureData(STORE_JSON_TOOLS).then(function (rows) {
    var tools = (rows || []).filter(function (r) { return r && r.id && String(r.id).indexOf("__") !== 0; });
    if (!tools.length) {
      content.innerHTML = '<div style="padding:24px; text-align:center; font-size:11px; color:#64748b; background:#f8fafc; border:1px dashed #cbd5e1;">No tools installed.</div>';
      return;
    }
    paint(tools);
  });

  function paint(tools) {
    content.innerHTML =
      '<div style="background:#fff; border:1px solid #e2e8f0; padding:10px; margin-bottom:8px; display:flex; gap:8px; align-items:center; flex-wrap:wrap;">' +
      '<label style="font-size:10px; font-weight:700; color:#64748b; text-transform:uppercase;">Tool:</label>' +
      '<select id="tasFixToolSel" style="flex:1; min-width:160px; padding:5px; font-size:11px; border:1px solid #cbd5e1;"><option value="">— pick —</option>' +
      tools.map(function (t) { return '<option value="' + _ebEsc(t.id) + '">' + _ebEsc(((t.catalog && t.catalog.icon) || "🧩") + " " + (t.label || t.id)) + ' (v' + (Number(t.__version) || 0) + ')</option>'; }).join("") +
      '</select>' +
      '<label style="font-size:10px; font-weight:700; color:#64748b; text-transform:uppercase;">Function:</label>' +
      '<select id="tasFixFnSel" style="flex:1; min-width:160px; padding:5px; font-size:11px; border:1px solid #cbd5e1;" disabled><option>— pick a tool first —</option></select>' +
      '</div>' +
      '<div id="tasFixBody"></div>';
    var toolSel = content.querySelector("#tasFixToolSel");
    var fnSel = content.querySelector("#tasFixFnSel");
    toolSel.onchange = function () {
      selectedTool = tools.filter(function (t) { return t.id === toolSel.value; })[0] || null;
      if (!selectedTool) { fnSel.disabled = true; fnSel.innerHTML = '<option>— pick a tool first —</option>'; return; }
      var fnNames = Object.keys(selectedTool.functions || {});
      fnSel.disabled = false;
      fnSel.innerHTML = '<option value="">— pick —</option>' +
        fnNames.map(function (n) { return '<option value="' + _ebEsc(n) + '">' + _ebEsc(n) + '</option>'; }).join("");
    };
    fnSel.onchange = function () {
      selectedFn = fnSel.value;
      if (!selectedTool || !selectedFn) return;
      originalSrc = selectedTool.functions[selectedFn] || "";
      proposedSrc = "";
      chat = _tasNewChat();
      paintBody();
    };
  }

  function paintBody() {
    var body = content.querySelector("#tasFixBody");
    // Vertical stack — taskpane is too narrow for side-by-side. Chat on top,
    // diff + apply below.
    body.innerHTML =
      '<div style="display:flex; flex-direction:column; gap:10px;">' +
      // TOP: chat
      '<div style="background:#fff; border:1px solid #e2e8f0; padding:10px; display:flex; flex-direction:column;">' +
      '<div style="font-size:10px; font-weight:800; color:#64748b; text-transform:uppercase; letter-spacing:0.5px; margin-bottom:6px;">🔧 DESCRIBE THE FIX</div>' +
      '<div id="tasFixChat" style="overflow-y:auto; min-height:140px; max-height:280px; padding:8px; background:#f8fafc; border:1px solid #e2e8f0; margin-bottom:8px;"></div>' +
      '<textarea id="tasFixInput" rows="3" placeholder="What\'s broken or what should change? e.g. \'It throws when there are no paragraphs — handle the empty case\' or \'add a max-results option\'" style="width:100%; padding:8px; font-size:12px; border:1px solid #cbd5e1; resize:vertical; box-sizing:border-box;"></textarea>' +
      '<div style="display:flex; gap:6px; margin-top:6px;">' +
      '<button id="tasFixSend" style="flex:1; padding:8px; font-size:11px; font-weight:800; background:linear-gradient(135deg,#6366f1,#4338ca); color:#fff; border:none; cursor:pointer;">📨 Send</button>' +
      '<button id="tasFixGen" style="flex:1; padding:8px; font-size:11px; font-weight:800; background:linear-gradient(135deg,#0d9488,#115e59); color:#fff; border:none; cursor:pointer;" title="Ask AI to emit the FINAL fixed function source">⚙️ Propose Fix</button>' +
      '</div>' +
      '</div>' +
      // BOTTOM: diff + source + apply buttons
      '<div style="background:#fff; border:1px solid #e2e8f0; padding:10px; display:flex; flex-direction:column;">' +
      '<div style="font-size:10px; font-weight:800; color:#64748b; text-transform:uppercase; letter-spacing:0.5px; margin-bottom:6px;">📋 DIFF (original → proposed)</div>' +
      '<div id="tasFixDiff" style="min-height:140px; max-height:240px; overflow:auto; padding:8px; background:#f8fafc; border:1px solid #e2e8f0; font-family:ui-monospace,Consolas,monospace; font-size:10px; line-height:1.45; white-space:pre-wrap; word-wrap:break-word; margin-bottom:8px;"></div>' +
      '<div style="font-size:9px; font-weight:700; color:#94a3b8; text-transform:uppercase; letter-spacing:0.5px; margin-bottom:4px;">Editable proposed source</div>' +
      '<textarea id="tasFixSrc" placeholder="// AI-proposed source will appear here. You can also edit it manually before applying." style="width:100%; min-height:160px; max-height:300px; padding:8px; font-family:ui-monospace,Consolas,monospace; font-size:10px; line-height:1.4; border:1px solid #cbd5e1; resize:vertical; box-sizing:border-box; white-space:pre; tab-size:2;"></textarea>' +
      '<div id="tasFixValOut" style="font-size:10px; margin:4px 0; min-height:14px;"></div>' +
      '<div style="display:flex; gap:6px;">' +
      '<button id="tasFixTest" style="flex:1; padding:8px; font-size:11px; font-weight:700; background:#fff; color:#7c3aed; border:1px solid #c4b5fd; cursor:pointer;" disabled>🧪 Test</button>' +
      '<button id="tasFixApply" style="flex:1; padding:8px; font-size:11px; font-weight:800; background:linear-gradient(135deg,#1565c0,#0d47a1); color:#fff; border:none; cursor:pointer;" disabled>💾 Apply</button>' +
      '<button id="tasFixDiscard" style="flex:1; padding:8px; font-size:11px; background:#fff; color:#64748b; border:1px solid #cbd5e1; cursor:pointer;">Discard</button>' +
      '</div>' +
      '</div>' +
      '</div>';

    var chatHost = body.querySelector("#tasFixChat");
    var input = body.querySelector("#tasFixInput");
    var btnSend = body.querySelector("#tasFixSend");
    var btnGen = body.querySelector("#tasFixGen");
    var diffHost = body.querySelector("#tasFixDiff");
    var srcArea = body.querySelector("#tasFixSrc");
    var valOut = body.querySelector("#tasFixValOut");
    var btnTest = body.querySelector("#tasFixTest");
    var btnApply = body.querySelector("#tasFixApply");
    var btnDiscard = body.querySelector("#tasFixDiscard");

    chatHost.innerHTML = '<div style="font-size:10px; color:#94a3b8; text-align:center; padding:18px;">Tell the AI what\'s wrong with <b>' + _ebEsc(selectedFn) + '</b>. It can ask follow-ups before proposing a fix.</div>';
    diffHost.innerHTML = '<div style="color:#94a3b8; font-style:italic;">No proposal yet. Click "Propose Fix" once you\'ve described the issue.</div>';
    srcArea.value = "";

    function refreshDiff() {
      proposedSrc = srcArea.value;
      if (!proposedSrc) {
        diffHost.innerHTML = '<div style="color:#94a3b8; font-style:italic;">No proposal yet.</div>';
        valOut.innerHTML = ""; btnTest.disabled = true; btnApply.disabled = true;
        return;
      }
      // Use the codebase's own redline renderer for consistency.
      if (typeof computeWordDiff === "function" && typeof renderSurgicalRedlineHtml === "function") {
        var hunks = computeWordDiff(originalSrc, proposedSrc);
        diffHost.innerHTML = renderSurgicalRedlineHtml(hunks);
      } else {
        diffHost.textContent = proposedSrc;
      }
      var err = _tasValidateSource(proposedSrc);
      if (err) {
        valOut.innerHTML = '<span style="color:#dc2626;">❌ ' + _ebEsc(err) + '</span>';
        btnTest.disabled = true; btnApply.disabled = true;
      } else {
        valOut.innerHTML = '<span style="color:#0d9488;">✓ Compiles cleanly.</span>';
        btnTest.disabled = false; btnApply.disabled = false;
      }
    }
    srcArea.addEventListener("input", refreshDiff);

    function callChat() {
      var sys =
        "You are a senior JavaScript debugger and rewriter for a Word add-in (ELI). " +
        "You're working on the function `" + selectedFn + "` from tool `" + selectedTool.id + "`. " +
        "Functions can use Word.run / Office APIs, callGemini, showToast, showEliDialog, document, window. " +
        "Ask 1-2 clarifying questions if useful. Don't emit the full revised source until the user says 'propose' or clicks Propose Fix. " +
        "When you do emit code, output ONLY the function source (starting with 'function " + selectedFn + "(') — no markdown fences, no prose.\n\n" +
        "ORIGINAL FUNCTION SOURCE:\n```\n" + originalSrc + "\n```";
      var prompt = _tasBuildChatPrompt(sys, chat);
      btnSend.disabled = true; btnGen.disabled = true;
      var oldText = btnSend.textContent;
      btnSend.textContent = "⏳…";
      return callGemini(API_KEY, prompt).then(function (resp) {
        var clean = String(resp || "").trim();
        _tasChatAppend(chat, "assistant", clean);
        _tasRenderChat(chat, chatHost);
        btnSend.disabled = false; btnGen.disabled = false; btnSend.textContent = oldText;
        return clean;
      }).catch(function (e) {
        btnSend.disabled = false; btnGen.disabled = false; btnSend.textContent = oldText;
        showToast("❌ AI error: " + (e && e.message ? e.message : "unknown"), "error");
        throw e;
      });
    }

    btnSend.onclick = function () {
      var text = input.value.trim();
      if (!text) { showToast("Type something first.", "warning"); return; }
      _tasChatAppend(chat, "user", text);
      input.value = "";
      _tasRenderChat(chat, chatHost);
      callChat();
    };
    input.addEventListener("keydown", function (e) {
      if (e.key === "Enter" && (e.ctrlKey || e.metaKey)) { e.preventDefault(); btnSend.click(); }
    });

    btnGen.onclick = function () {
      if (chat.messages.length === 0) {
        // Allow direct fix without chat — just use the most recent user input.
        var text = input.value.trim();
        if (!text) { showToast("Describe the fix or have a chat first.", "warning"); return; }
        _tasChatAppend(chat, "user", text);
        input.value = "";
      }
      _tasChatAppend(chat, "user",
        "OK, please now emit the FINAL revised source for `" + selectedFn + "`. " +
        "Output ONLY the JavaScript function source — starting with 'function " + selectedFn + "(' and ending with the closing brace. " +
        "No markdown fences, no prose, no commentary. Preserve the function name and signature exactly. " +
        "IMPORTANT: format as MULTI-LINE code with real newlines and 2-space indentation. Do NOT minify or join statements onto one line."
      );
      _tasRenderChat(chat, chatHost);
      callChat().then(function (resp) {
        var src = _tasCleanCode(resp);
        if (!/^function\s+/i.test(src)) {
          showToast("⚠️ AI response didn't look like a function — review and edit manually.", "warning");
        }
        // Beautify single-line minified output from the AI.
        if (typeof _tasBeautifyJs === "function") src = _tasBeautifyJs(src);
        srcArea.value = src;
        refreshDiff();
      });
    };

    btnTest.onclick = function () {
      try {
        // Sandbox: make a copy of the tool with the proposed function and try the catalog action.
        var copy = JSON.parse(JSON.stringify(selectedTool));
        copy.functions[selectedFn] = proposedSrc;
        Object.keys(copy.functions).forEach(function (n) {
          window[n] = new Function("return (\n" + copy.functions[n] + "\n);")();
        });
        if (copy.catalog && copy.catalog.action) {
          var fn = new Function(copy.catalog.action);
          fn();
          showToast("🧪 Test fired — check the output area.", "info");
        } else {
          showToast("✓ Function compiles. No catalog.action to invoke.", "success");
        }
      } catch (e) {
        showToast("❌ Test failed: " + (e && e.message ? e.message : "unknown"), "error");
      }
    };

    btnApply.onclick = function () {
      var err = _tasValidateSource(proposedSrc);
      if (err) { showToast("❌ Won't apply — " + err, "error"); return; }
      _tasSnapshotTool(selectedTool); // backup current version BEFORE overwriting
      selectedTool.functions[selectedFn] = proposedSrc;
      selectedTool.__version = (Number(selectedTool.__version) || 0) + 1;
      _tasSaveTool(selectedTool).then(function () {
        showToast("✓ Applied fix to " + selectedFn + " (v" + selectedTool.__version + "). Snapshot saved for rollback in History tab.", "success");
        originalSrc = proposedSrc;
        proposedSrc = "";
        srcArea.value = "";
        refreshDiff();
      });
    };
    btnDiscard.onclick = function () {
      proposedSrc = "";
      srcArea.value = "";
      refreshDiff();
      showToast("Discarded.", "info");
    };
  }
}

functions._tasImportExportTab:
function _tasImportExportTab(content) {
  content.innerHTML =
    '<div style="display:grid; grid-template-columns:1fr 1fr; gap:12px;">' +
    // Import column
    '<div style="background:#fff; border:1px solid #e2e8f0; padding:12px;">' +
    '<div style="font-size:10px; font-weight:800; color:#64748b; text-transform:uppercase; letter-spacing:0.5px; margin-bottom:6px;">📥 IMPORT</div>' +
    '<div style="font-size:10px; color:#94a3b8; margin-bottom:6px;">Paste a JSON tool object (or a full payload with sections.jsonTools[]).</div>' +
    '<textarea id="tasIeIn" rows="14" placeholder="{ &quot;id&quot;: &quot;my_tool&quot;, &quot;label&quot;: &quot;...&quot;, ... }" style="width:100%; padding:8px; font-family:ui-monospace,Consolas,monospace; font-size:10px; line-height:1.4; border:1px solid #cbd5e1; resize:vertical; box-sizing:border-box; white-space:pre; tab-size:2; min-height:280px;"></textarea>' +
    '<div id="tasIeInOut" style="font-size:10px; margin:6px 0; min-height:14px;"></div>' +
    '<div style="display:flex; gap:6px;">' +
    '<button id="tasIeValidate" style="flex:1; padding:8px; font-size:11px; font-weight:700; background:#fff; color:#0d9488; border:1px solid #0d9488; cursor:pointer;">🧪 Validate</button>' +
    '<button id="tasIeInstall" style="flex:1; padding:8px; font-size:11px; font-weight:800; background:linear-gradient(135deg,#1565c0,#0d47a1); color:#fff; border:none; cursor:pointer;" disabled>📥 Install</button>' +
    '</div>' +
    '</div>' +
    // Export column
    '<div style="background:#fff; border:1px solid #e2e8f0; padding:12px;">' +
    '<div style="font-size:10px; font-weight:800; color:#64748b; text-transform:uppercase; letter-spacing:0.5px; margin-bottom:6px;">📤 EXPORT</div>' +
    '<div id="tasIeExportList" style="font-size:11px; color:#94a3b8;">Loading…</div>' +
    '<div style="margin-top:8px;">' +
    '<div id="tasIeExportPreview" style="font-size:10px; color:#94a3b8; font-style:italic;">Pick a tool to preview its JSON.</div>' +
    '<textarea id="tasIeExportText" rows="10" readonly style="width:100%; margin-top:6px; padding:8px; font-family:ui-monospace,Consolas,monospace; font-size:10px; line-height:1.4; border:1px solid #cbd5e1; box-sizing:border-box; white-space:pre; tab-size:2; display:none;"></textarea>' +
    '<button id="tasIeCopy" style="margin-top:6px; padding:8px 12px; font-size:11px; font-weight:700; background:#fff; color:#1565c0; border:1px solid #1565c0; cursor:pointer; display:none;">📋 Copy to clipboard</button>' +
    '</div>' +
    '</div>' +
    '</div>';

  var inArea = content.querySelector("#tasIeIn");
  var inOut  = content.querySelector("#tasIeInOut");
  var btnVal = content.querySelector("#tasIeValidate");
  var btnInstall = content.querySelector("#tasIeInstall");
  var listHost = content.querySelector("#tasIeExportList");
  var prevHost = content.querySelector("#tasIeExportPreview");
  var prevText = content.querySelector("#tasIeExportText");
  var btnCopy  = content.querySelector("#tasIeCopy");
  var pendingTool = null;

  function tryParse() {
    var raw = inArea.value.trim();
    if (!raw) return null;
    try {
      var obj = JSON.parse(raw);
      // Allow either a full payload (sections.jsonTools[0]) or a bare tool object.
      if (obj.sections && obj.sections.jsonTools && obj.sections.jsonTools[0]) return obj.sections.jsonTools[0];
      return obj;
    } catch (e) { return { _parseError: e.message }; }
  }

  function validateTool(t) {
    if (!t || typeof t !== "object") return "Not an object";
    if (!t.id || typeof t.id !== "string") return "Missing or invalid 'id'";
    if (t.functions && typeof t.functions !== "object") return "'functions' must be an object";
    if (t.functions) {
      var bad = "";
      Object.keys(t.functions).forEach(function (n) {
        if (bad) return;
        var err = _tasValidateSource(t.functions[n]);
        if (err) bad = "Function '" + n + "': " + err;
      });
      if (bad) return bad;
    }
    return null;
  }

  btnVal.onclick = function () {
    var t = tryParse();
    if (!t) { inOut.innerHTML = '<span style="color:#94a3b8;">Empty.</span>'; pendingTool = null; btnInstall.disabled = true; return; }
    if (t._parseError) { inOut.innerHTML = '<span style="color:#dc2626;">❌ JSON parse error: ' + _ebEsc(t._parseError) + '</span>'; pendingTool = null; btnInstall.disabled = true; return; }
    var err = validateTool(t);
    if (err) { inOut.innerHTML = '<span style="color:#dc2626;">❌ ' + _ebEsc(err) + '</span>'; pendingTool = null; btnInstall.disabled = true; return; }
    inOut.innerHTML = '<span style="color:#0d9488;">✓ Valid. Tool id: <b>' + _ebEsc(t.id) + '</b> · ' + (t.functions ? Object.keys(t.functions).length : 0) + ' function(s).</span>';
    pendingTool = t;
    btnInstall.disabled = false;
  };
  btnInstall.onclick = function () {
    if (!pendingTool) return;
    if (!pendingTool.__version) pendingTool.__version = 1;
    _tasSaveTool(pendingTool).then(function () {
      if (pendingTool.catalog && typeof _tasSaveCatalogRow === "function") {
        _tasSaveCatalogRow(pendingTool.catalog).catch(function () {});
      }
      showToast("✓ Installed " + pendingTool.id + " (v" + pendingTool.__version + ").", "success");
      // Refresh the export list since a new tool now exists.
      loadExportList();
    });
  };

  function loadExportList() {
    loadFeatureData(STORE_JSON_TOOLS).then(function (rows) {
      var tools = (rows || []).filter(function (r) { return r && r.id && String(r.id).indexOf("__") !== 0; });
      if (!tools.length) { listHost.innerHTML = '<span style="color:#94a3b8;">No tools installed.</span>'; return; }
      listHost.innerHTML = tools.map(function (t) {
        return '<div data-tas-export="' + _ebEsc(t.id) + '" style="padding:6px 8px; border:1px solid #e2e8f0; margin-bottom:3px; cursor:pointer; font-size:11px; color:#0f172a; display:flex; justify-content:space-between; align-items:center;">' +
          '<span>' + _ebEsc(((t.catalog && t.catalog.icon) || "🧩") + " " + (t.label || t.id)) + '</span>' +
          '<span style="font-size:9px; color:#64748b;">v' + (Number(t.__version) || 0) + '</span>' +
          '</div>';
      }).join("");
      listHost.querySelectorAll("[data-tas-export]").forEach(function (row) {
        row.onclick = function () {
          var id = row.getAttribute("data-tas-export");
          var t = tools.filter(function (x) { return x.id === id; })[0];
          if (!t) return;
          prevHost.innerHTML = '<div style="font-size:10px; color:#0f172a;">Selected: <b>' + _ebEsc(t.id) + '</b> (v' + (Number(t.__version) || 0) + ')</div>';
          prevText.value = JSON.stringify(t, null, 2);
          prevText.style.display = "block";
          btnCopy.style.display = "inline-block";
          btnCopy.onclick = function () {
            prevText.select();
            try { document.execCommand("copy"); showToast("📋 Copied " + t.id + " to clipboard.", "success"); }
            catch (_) { showToast("Copy failed — select manually.", "warning"); }
          };
        };
      });
    });
  }
  loadExportList();
}

functions._tasHistoryTab:
function _tasHistoryTab(content) {
  content.innerHTML = '<div style="padding:14px; text-align:center; font-size:11px; color:#94a3b8;">Loading…</div>';
  loadFeatureData(STORE_JSON_TOOLS).then(function (rows) {
    var tools = (rows || []).filter(function (r) { return r && r.id && String(r.id).indexOf("__") !== 0; });
    if (!tools.length) {
      content.innerHTML = '<div style="padding:24px; text-align:center; font-size:11px; color:#64748b; background:#f8fafc; border:1px dashed #cbd5e1;">No tools installed.</div>';
      return;
    }
    var hasAny = tools.some(function (t) { return _tasGetHistory(t.id).length > 0; });
    if (!hasAny) {
      content.innerHTML = '<div style="padding:24px; text-align:center; font-size:11px; color:#64748b; background:#f8fafc; border:1px dashed #cbd5e1;">No snapshots yet. Snapshots are auto-saved when you Apply an AI Fix or Save in Edit Tool Source.</div>';
      return;
    }
    var html =
      '<div style="font-size:10px; color:#64748b; margin-bottom:8px;">Snapshots are kept in localStorage (last 10 per tool). Click "Restore" to revert.</div>';
    tools.forEach(function (t) {
      var hist = _tasGetHistory(t.id);
      if (!hist.length) return;
      html += '<div style="background:#fff; border:1px solid #e2e8f0; padding:10px; margin-bottom:8px;">' +
        '<div style="font-size:12px; font-weight:800; color:#0f172a; margin-bottom:6px;">' + _ebEsc(((t.catalog && t.catalog.icon) || "🧩") + " " + (t.label || t.id)) + ' <span style="font-size:9px; color:#64748b;">(currently v' + (Number(t.__version) || 0) + ')</span></div>';
      hist.forEach(function (h, i) {
        var when = new Date(h.at);
        var fnNames = h.tool && h.tool.functions ? Object.keys(h.tool.functions) : [];
        html += '<div style="display:flex; justify-content:space-between; align-items:center; padding:5px 8px; border:1px solid #e2e8f0; margin-bottom:3px; background:' + (i % 2 ? "#f8fafc" : "#fff") + ';">' +
          '<div style="font-size:10px; color:#334155;">' +
          '<b>v' + h.version + '</b>' +
          ' · ' + when.toLocaleString() +
          ' · ' + fnNames.length + ' fn' +
          '</div>' +
          '<div style="display:flex; gap:4px;">' +
          '<button data-tas-hist-prev="' + _ebEsc(t.id) + '|' + i + '" style="padding:3px 8px; font-size:10px; background:#fff; color:#1565c0; border:1px solid #1565c0; cursor:pointer;">Preview</button>' +
          '<button data-tas-hist-restore="' + _ebEsc(t.id) + '|' + i + '" style="padding:3px 8px; font-size:10px; background:#fff; color:#dc2626; border:1px solid #dc2626; cursor:pointer;">Restore</button>' +
          '</div>' +
          '</div>';
      });
      html += '</div>';
    });
    content.innerHTML = html;

    content.querySelectorAll("[data-tas-hist-prev]").forEach(function (btn) {
      btn.onclick = function () {
        var parts = btn.getAttribute("data-tas-hist-prev").split("|");
        var hist = _tasGetHistory(parts[0]);
        var snap = hist[Number(parts[1])];
        if (!snap) return;
        var pretty = JSON.stringify(snap.tool, null, 2);
        if (typeof showEliDialog === "function") {
          showEliDialog({
            variant: "info", icon: "🕒", title: "Snapshot v" + snap.version + " (" + new Date(snap.at).toLocaleString() + ")",
            body: '<textarea readonly style="width:100%; height:380px; padding:8px; font-family:ui-monospace,Consolas,monospace; font-size:10px; line-height:1.4; border:1px solid #cbd5e1; box-sizing:border-box; white-space:pre; tab-size:2;">' + _ebEsc(pretty) + '</textarea>',
            buttons: [{ id: "tasHistPrevClose", label: "Close", passthrough: true, style: "flex:1;",
              onclick: function () { var n = document.getElementById("tasHistPrevClose"); if (n && n.closest(".eli-overlay")) n.closest(".eli-overlay").remove(); } }],
          });
        }
      };
    });
    content.querySelectorAll("[data-tas-hist-restore]").forEach(function (btn) {
      btn.onclick = function () {
        var parts = btn.getAttribute("data-tas-hist-restore").split("|");
        var toolId = parts[0];
        var hist = _tasGetHistory(toolId);
        var snap = hist[Number(parts[1])];
        if (!snap) return;
        var current = tools.filter(function (t) { return t.id === toolId; })[0];
        if (!current) return;
        // Snapshot current BEFORE restoring (so the restore itself is also undo-able).
        _tasSnapshotTool(current);
        var restored = JSON.parse(JSON.stringify(snap.tool));
        restored.__version = (Number(current.__version) || 0) + 1; // bump so loader picks it up
        _tasSaveTool(restored).then(function () {
          showToast("✓ Restored " + toolId + " to snapshot from " + new Date(snap.at).toLocaleString() + " (now v" + restored.__version + ").", "success");
          _tasHistoryTab(content); // re-render
        });
      };
    });
  });
}
